#include "stdafx.h"

// =============================================================================
//  (th4) DANISH localization (LANG_DA). Mirrors LocalizationTR.cpp structure.
//
//  ENCODING: raw CP1252 bytes (latin-1 on disk). Danish needs three letters
//  beyond ASCII, and all of them sit in CP1252 with glyphs already present in
//  the Portuguese MID/BIG CEL frames:
//        0xC5 A-ring   0xE5 a-ring
//        0xC6 AE       0xE6 ae
//        0xD8 O-slash  0xF8 o-slash
//  RULES (same as PT/FR):
//    * Dedicated functions (DA_TraitName etc.) and Speech/OnScreen/Quest rows
//      may use the real accented bytes above.
//    * Overlay UiStr tables ASCII-FOLD: ae for \xe6, oe for \xf8, aa for \xe5
//      (Danish's own pre-1948 spellings), and likewise Ae/Oe/Aa capitalised.
//    * \xNN followed by a literal hex digit needs a "" break (greedy-hex trap).
//
//  ---- STATUS -------------------------------------------------------------
//  SCAFFOLD ONLY. Every table holds a lone placeholder => 0 rows => the whole
//  UI falls back to English. This is a valid, shippable state: selecting
//  language 12 gives a working English build with the Danish font path active.
//  Fill tables in batches; keys must byte-exactly match the English source
//  literal or the row is silently ignored.
// =============================================================================

struct UiStr  { const char* en; const char* da; }; // .da column holds the DA text
struct IdxStr { int index; const char* da; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

