// (th4) Menu screens. ASCII-FOLDED on purpose (ae / oe / aa): these strings render
// through the meta-menu sheets ui_art\\font16/24/30/42, which Codepage_Danish does NOT
// cover -- that fold only reaches the CEL fonts. FR and DE keep this table ASCII for
// the same reason. The subclass names are copied verbatim from DA_Ui so the villain
// picker and the character panel can never disagree.
