// (th4) NPC speech, COMPLETE: all 464 rows. Real CP1252 bytes. Covers every
// classic quest arc, all town gossip, Hellfire content (Na-Krul journals, Grimspike,
// Horazon, farmer/Celia/Theo), TH additions (Fleshdoom/Shadowfang, Izual, Sunless
// Sea, treasure map, trade quests) and the full Dark Campaign briefing set (449-478).
static const IdxStr DA_Speech[] = {
	{ 0, " Ahh, historien om vor konge, ikke sandt? Leorics tragiske fald var et h\xe5rdt slag for dette land. Folket elskede altid kongen, og nu lever de i d\xf8""delig frygt for ham. Det sp\xf8rgsm\xe5l, jeg bliver ved at stille mig selv, er, hvordan han kunne falde s\xe5 langt fra Lyset, n\xe5r Leoric altid havde v\xe6ret den helligste af m\xe6nd. Kun Helvedes nedrigste kr\xe6""fter kunne s\xe5 fuldst\xe6ndigt \xf8""del\xe6gge en mand indefra... |" },
	{ 1, "Landsbyen har brug for din hj\xe6lp, gode mester! For nogle m\xe5neder siden blev kong Leorics s\xf8n, prins Albrecht, bortf\xf8rt. Kongen gik i raseri og endevendte landsbyen efter sit forsvundne barn. For hver dag der gik, syntes Leoric at glide dybere ned i galskab. Han s\xf8gte at give uskyldige byboere skylden for drengens forsvinden og lod dem brutalt henrette. Under halvdelen af os overlevede hans vanvid...\n \nKongens riddere og pr\xe6ster fors\xf8gte at berolige ham, men han vendte sig mod dem, og s\xf8rgeligt nok blev de tvunget til at dr\xe6""be ham. Med sit sidste \xe5ndedrag nedkaldte kongen en frygtelig forbandelse over sine tidligere f\xf8lgesvende. Han svor, at de skulle tjene ham i m\xf8rket for evigt...\n \nOg her tager tingene en endnu m\xf8rkere drejning, end jeg troede muligt! Vor tidligere konge har rejst sig fra sin evige s\xf8vn og kommanderer nu en legion af ud\xf8""de h\xe5ndlangere i labyrinten. Hans krop blev gravlagt i en grav tre etager under katedralen. Jeg beder dig, gode mester, giv hans sj\xe6l fred ved at tilintetg\xf8re hans nu forbandede skikkelse... |" },
	{ 2, "Som jeg fortalte dig, gode mester, blev kongen gravlagt tre etager nede. Han er dernede og venter i det r\xe5""dne m\xf8rke p\xe5 sin chance for at \xf8""del\xe6gge dette land... |" },
	{ 3, "Vor konges forbandelse er forbi, men jeg frygter, at den kun var en del af et st\xf8rre onde. Dog kan vi endnu reddes fra det m\xf8rke, der fort\xe6rer vort land, for din sejr er et godt varsel. M\xe5 Lyset lede dig p\xe5 din vej, gode mester. |" },
	{ 4, "Tabet af hans s\xf8n var for meget for kong Leoric. Jeg gjorde, hvad jeg kunne, for at lindre hans galskab, men til sidst overmandede den ham. En sort forbandelse har h\xe6ngt over dette kongerige siden den dag, men m\xe5ske, hvis du befriede hans \xe5nd fra dens jordiske f\xe6ngsel, ville forbandelsen blive h\xe6vet... |" },
	{ 5, "Jeg bryder mig ikke om at t\xe6nke p\xe5, hvordan kongen d\xf8""de. Jeg vil huske ham som den venlige og retf\xe6rdige hersker, han var. Hans d\xf8""d var s\xe5 trist og virkede p\xe5 en eller anden m\xe5""de helt forkert. |" },
	{ 6, "Jeg smedede mange af de v\xe5""ben og det meste af den rustning, kong Leoric udrustede sine riddere med. Jeg lavede endda et v\xe6ldigt toh\xe5ndssv\xe6rd af fineste mithril til ham, samt en feltkrone der passede til. Jeg kan stadig ikke fatte, hvordan han d\xf8""de, men det m\xe5 have v\xe6ret en ondsindet kraft, der drev ham til vanvid! |" },
	{ 7, "Det rager mig. H\xf8r her, intet skelet skal v\xe6re MIN konge. Leoric er konge. Konge, h\xf8rer du? L\xc6NGE LEVE KONGEN! |" },
	{ 8, "De d\xf8""de, der vandrer blandt de levende, f\xf8lger den forbandede konge. Han besidder magten til at rejse endnu flere krigere til en stadigt voksende h\xe6r af ud\xf8""de. Hvis du ikke standser hans herred\xf8mme, vil han med sikkerhed marchere gennem dette land og dr\xe6""be alle, der endnu lever her. |" },
	{ 9, "H\xf8r, jeg driver en forretning her. Jeg s\xe6lger ikke oplysninger, og jeg er ligeglad med en konge, der har v\xe6ret d\xf8""d l\xe6ngere, end jeg har levet. Har du brug for noget at bruge mod denne de ud\xf8""des konge, s\xe5 kan jeg hj\xe6lpe dig... |" },
	{ 10, "Livets varme er tr\xe5""dt ind i min grav. Bered dig, d\xf8""delige, p\xe5 at tjene min Herre i al evighed! |" },
	{ 11, "Jeg ser, at denne s\xe6lsomme opf\xf8rsel ogs\xe5 undrer dig. Jeg vil formode, at eftersom mange d\xe6moner frygter solens lys og tror, det rummer stor kraft, kan den opg\xe5""ende sol p\xe5 skiltet, du taler om, have f\xe5""et dem til at tro, at det ogs\xe5 rummer arkane kr\xe6""fter. Hmm, m\xe5ske er de ikke alle s\xe5 kloge, som vi frygtede... |" },
	{ 12, "Mester, jeg har en s\xe6lsom oplevelse at berette. Jeg ved, at du har stor viden om de uhyrligheder, der bebor labyrinten, og dette er noget, jeg for mit bare liv ikke kan forst\xe5... Jeg blev v\xe6kket i nat af en skrabende lyd lige uden for min kro. Da jeg kiggede ud fra mit sovekammer, s\xe5 jeg skikkelser af sm\xe5 d\xe6monagtige v\xe6sner i g\xe5rden. Efter kort tid l\xf8""b de deres vej, men ikke f\xf8r de havde stj\xe5let skiltet til min kro. Jeg ved ikke, hvorfor d\xe6monerne ville stj\xe6le mit skilt men lade min familie v\xe6re i fred... s\xe6lsomt, ikke? |" },
	{ 13, "\xc5h, du havde ikke beh\xf8vet at bringe mit skilt tilbage, men det sparer mig vel udgiften til at f\xe5 lavet et nyt. Lad mig se, hvad kunne jeg give dig som l\xf8n for at finde det? Hmmm, hvad har vi her... ah, ja! Denne hue blev efterladt i et af v\xe6relserne af en magiker, der boede her for nogen tid siden. M\xe5ske kan den v\xe6re dig til nytte. |" },
	{ 14, "Du milde, d\xe6moner der render rundt i landsbyen om natten og pl\xf8ndrer vore hjem - er intet helligt? Jeg h\xe5""ber, Ogden og Garda er uskadte. De ville vel komme til mig, hvis de var kommet til skade... |" },
	{ 15, "Ih du store! Var det d\xe9r, skiltet blev af? Min bedstemor og jeg m\xe5 have sovet gennem det hele. Lyset v\xe6re lovet, at de monstre ikke angreb kroen. |" },
	{ 16, "D\xe6moner stjal Ogdens skilt, siger du? Det lyder ikke meget som de gr\xe6sligheder, jeg har h\xf8rt om - eller set. \n \nD\xe6moner g\xe5r op i at fl\xe5 dit hjerte ud, ikke dit skilt. |" },
	{ 17, "Ved du, hvad jeg tror? Nogen tog det skilt, og de vil have mange penge for det. Hvis jeg var Ogden... og det er jeg ikke, men hvis jeg var... s\xe5 ville jeg bare k\xf8""be et nyt skilt med en p\xe6n tegning p\xe5. M\xe5ske et fint krus \xf8l eller et stykke ost... |" },
	{ 18, "Ingen d\xf8""delig kan i sandhed forst\xe5 d\xe6monens sind. \n \nLad aldrig deres uberegnelige handlinger forvirre dig, for ogs\xe5 det kan v\xe6re deres plan. |" },
	{ 19, "Hvad - siger han, at jeg tog det? S\xe5 er Griswold vel ogs\xe5 p\xe5 hans side. \n \nH\xf8r, jeg voksede fra simpelt skiltetyveri for m\xe5neder siden. Man kan ikke tjene p\xe5 et stykke tr\xe6. |" },
	{ 20, "Hej - dig der som dr\xe6""ber alle! Du skaffe mig magisk banner, eller vi angriber! Du ikke g\xe5r herfra i live! Du dr\xe6""b store grimme og giv magi tilbage. G\xe5 forbi hj\xf8rne og d\xf8r, find grimme. Du giv, du g\xe5! |" },
	{ 21, "Du dr\xe6""b grimme, tag banner. Du bring til mig, ellers... |" },
	{ 22, "Du giv! Ja, godt! G\xe5 nu, vi st\xe6rke. Vi dr\xe6""b alle med stor magi! |" },
	{ 23, "Dette lover ikke godt, for det bekr\xe6""fter mine m\xf8rkeste anelser. Sk\xf8nt jeg ikke tillod mig selv at tro p\xe5 de gamle sagn, kan jeg ikke ben\xe6gte dem nu. M\xe5ske er tiden inde til at afsl\xf8re, hvem jeg er.\n \nMit sande navn er Deckard Cain den \xc6ldre, og jeg er den sidste efterkommer af et \xe6ldgammelt broderskab, viet til at vogte hemmelighederne om et tidl\xf8st onde. Et onde, som nu \xe5""benlyst er sluppet l\xf8s.\n \n\xc6rkebiskop Lazarus, engang kong Leorics mest betroede r\xe5""dgiver, f\xf8rte en flok j\xe6vne byboere ind i labyrinten for at finde kongens forsvundne s\xf8n, Albrecht. Der gik lang tid, f\xf8r de vendte tilbage, og kun f\xe5 slap fra det med livet.\n \nForband mig for et fjols! Jeg burde have anet hans skjulte forr\xe6""deri dengang. Det m\xe5 have v\xe6ret Lazarus selv, der bortf\xf8rte Albrecht og siden har skjult ham i labyrinten. Jeg forst\xe5r ikke, hvorfor \xe6rkebiskoppen vendte sig mod m\xf8rket, eller hvad hans interesse i barnet er, medmindre han agter at ofre ham til sine m\xf8rke herrer!\n \nDet m\xe5 v\xe6re, hvad han har planlagt! De overlevende fra hans 'redningshold' siger, at Lazarus sidst blev set l\xf8""be ned i labyrintens dybeste indvolde. Du m\xe5 skynde dig og redde prinsen fra denne afsindige dj\xe6vels offerklinge! |" },
	{ 24, "Du m\xe5 skynde dig og redde Albrecht fra Lazarus' h\xe6nder. Prinsen og folket i dette kongerige regner med dig! |" },
	{ 25, "Din beretning er s\xf8rgelig, min ven. Lazarus vil med sikkerhed br\xe6nde i Helvede for sin gr\xe6sselige gerning. Drengen, du beskriver, er ikke vor prins, men jeg tror, at Albrecht stadig kan v\xe6re i fare. Magtsymbolet, du taler om, m\xe5 v\xe6re en portal i selve labyrintens hjerte.\n \nVid dette, min ven - det onde, du drager imod, er R\xe6""dslens m\xf8rke Herre. D\xf8""delige kender ham som Diablo. Det var ham, der blev f\xe6ngslet i labyrinten for mange \xe5rhundreder siden, og jeg frygter, at han atter s\xf8ger at s\xe5 kaos i menneskenes rige. Du m\xe5 g\xe5 gennem portalen og tilintetg\xf8re Diablo, f\xf8r det er for sent! |" },
	{ 26, "Lazarus var \xe6rkebiskoppen, der f\xf8rte mange af byens folk ind i labyrinten. Jeg mistede mange gode venner den dag, og Lazarus vendte aldrig tilbage. Han blev vel dr\xe6""bt sammen med de fleste andre. Hvis du vil g\xf8re mig en tjeneste, gode mester - tal ikke med Farnham om den dag. |" },
	{ 29, "Jeg blev rystet, da jeg h\xf8rte, hvad byens folk havde t\xe6nkt sig at g\xf8re den nat. Jeg troede, at Lazarus af alle ville have haft mere forstand end som s\xe5. Han var \xe6rkebiskop og syntes altid at have stor omsorg for Tristrams borgere. S\xe5 mange kom til skade, jeg kunne ikke redde dem alle... |" },
	{ 30, "Jeg husker Lazarus som en meget venlig og gavmild mand. Han talte ved min mors begravelse og var en st\xf8tte for min bedstemor og mig i en meget sv\xe6r tid. Jeg beder hver aften om, at han p\xe5 en eller anden m\xe5""de stadig er i live og i sikkerhed. |" },
	{ 31, "Jeg var der, da Lazarus f\xf8rte os ind i labyrinten. Han talte om hellig geng\xe6ldelse, men da vi begyndte at k\xe6mpe mod de helvedesyngel, l\xf8""ftede han ikke s\xe5 meget som sin stridsk\xf8lle mod dem. Han l\xf8""b bare dybere ind i de dunkle, endel\xf8se kamre, der var fyldt med m\xf8rkets tjenere! |" },
	{ 32, "De stikker, s\xe5 bider de, s\xe5 er de overalt omkring dig. L\xf8gner! L\xd8GNER! De er alle d\xf8""de! D\xf8""de! H\xf8rer du mig? De bliver bare ved med at falde og falde... deres blod flyder ud over hele gulvet... alt sammen hans skyld... |" },
	{ 33, "Jeg kendte ikke denne Lazarus, du taler om, men jeg fornemmer en stor splid i hans v\xe6sen. Han udg\xf8r en stor fare og vil intet sky for at tjene de m\xf8rkets magter, der har gjort krav p\xe5 ham. |" },
	{ 34, "Ja, den retf\xe6rdige Lazarus, som var s\xe5\xe5\xe5 effektiv mod de monstre dernede. Hjalp det mit ben? H\xf8r, jeg giver dig et gratis r\xe5""d. Sp\xf8rg Farnham, han var der. |" },
	{ 35, "Opgiv din t\xe5""belige f\xe6rd. Alt, der venter dig, er min Herres vrede! Du er for sent ude til at redde barnet. Nu skal du f\xf8lge ham til Helvede! |" },
	{ 37, "Hmm, jeg ved ikke, hvad jeg egentlig kan fort\xe6lle dig om dette, som vil v\xe6re til nogen hj\xe6lp. Vandet, der fylder vore br\xf8nde, kommer fra en underjordisk kilde. Jeg har h\xf8rt om en tunnel, der f\xf8rer til en stor s\xf8 - m\xe5ske er de \xe9t og det samme. Desv\xe6rre ved jeg ikke, hvad der kunne besmitte vores vandforsyning. |" },
	{ 38, "Jeg har altid fors\xf8gt at holde et stort lager af mad og drikke i vores k\xe6lder, men n\xe5r hele byen ingen kilde til frisk vand har, l\xf8""ber selv vore forr\xe5""d snart t\xf8rre. \n \nJeg beder dig, g\xf8r hvad du kan, ellers ved jeg ikke, hvad vi skal g\xf8re. |" },
	{ 39, "Godt, jeg n\xe5""ede dig i tide! Vore br\xf8nde er blevet brakke og stillest\xe5""ende, og nogle af byens folk er blevet syge af at drikke af dem. Vore reserver af frisk vand svinder hurtigt. Jeg tror, der findes en passage, som f\xf8rer til de kilder, der forsyner vores by. Find \xe5rsagen til denne ulykke, ellers g\xe5r vi alle til grunde. |" },
	{ 40, "Jeg beder dig, skynd dig. For hver time der g\xe5r, kommer vi n\xe6rmere p\xe5 slet intet drikkevand at have. \n \nVi kan ikke overleve l\xe6nge uden din hj\xe6lp. |" },
	{ 41, "Hvad siger du - alene d\xe6monernes tilstedev\xe6relse har besmittet vandet? Ak, i sandhed lurer et stort onde under vores by, men din udholdenhed og dit mod giver os h\xe5""b. Tag denne ring - m\xe5ske vil den hj\xe6lpe dig med at tilintetg\xf8re den slags nedrige v\xe6sner. |" },
	{ 42, "Min bedstemor er meget svag, og Garda siger, at vi ikke kan drikke vandet fra br\xf8ndene. Kan du ikke g\xf8re noget for at hj\xe6lpe os? |" },
	{ 43, "Pepin har talt sandt. Vi f\xe5r h\xe5rdt brug for frisk vand, og det snart. Jeg har fors\xf8gt at rense en af de mindre br\xf8nde, men den stinker af stillest\xe5""ende snavs. Den m\xe5 v\xe6re ved at stoppe til ved kilden. |" },
	{ 44, "Drikker du vand? |" },
	{ 45, "Tristrams folk vil d\xf8, hvis du ikke kan genoprette frisk vand i deres br\xf8nde. \n \nVid dette - d\xe6moner er sagens kerne, men de er uvidende om, hvad de har afstedkommet. |" },
	{ 46, "For en gangs skyld er jeg med dig. Min forretning l\xf8""ber t\xf8r - s\xe5 at sige - hvis jeg intet marked har at s\xe6lge til. Du m\xe5 hellere finde ud af, hvad der foreg\xe5r, og det hurtigt! |" },
	{ 47, "En bog, der taler om et kammer af menneskeknogler? Nuvel, et knoglekammer n\xe6vnes i visse arkaiske skrifter, jeg studerede i \xd8stens biblioteker. Disse folianter antydede, at n\xe5r underverdenens herrer \xf8nskede at beskytte store skatte, skabte de omr\xe5""der, hvor de, der d\xf8""de i fors\xf8get p\xe5 at stj\xe6le skatten, for evigt ville v\xe6re bundet til at forsvare den. En forkvaklet, men s\xe6lsomt passende, afslutning? |" },
	{ 48, "Det ved jeg desv\xe6rre intet om, gode mester. Cain har mange b\xf8ger, der m\xe5ske kan hj\xe6lpe. |" },
	{ 49, "Det lyder som et meget farligt sted. Hvis du drager derhen, s\xe5 pas godt p\xe5. |" },
	{ 50, "Det har jeg desv\xe6rre intet h\xf8rt om. M\xe5ske kan fort\xe6lleren Cain v\xe6re til hj\xe6lp. |" },
	{ 51, "Jeg kender intet til dette sted, men du kan pr\xf8ve at sp\xf8rge Cain. Han taler om mange ting, og det ville ikke undre mig, om han havde svar p\xe5 dine sp\xf8rgsm\xe5l. |" },
	{ 52, "Okay, s\xe5 h\xf8r her. Der er det her kammer af tr\xe6, ikke. Og hans kone, du ved - hende - fort\xe6ller tr\xe6""et... for man skal vente. S\xe5 siger jeg, det kunne m\xe5ske virke mod ham, men hvis du tror, jeg vil BETALE for det her... s\xe5... \xf8h... ja. |" },
	{ 53, "Du bliver en evig tjener for de m\xf8rke herrer, hvis du omkommer i dette forbandede rige. \n \nTr\xe6""d ind i Knoglekammeret p\xe5 egen risiko. |" },
	{ 54, "En v\xe6ldig og g\xe5""defuld skat, siger du? M\xe5ske kunne jeg v\xe6re interesseret i at k\xf8""be et par ting af dig... eller endnu bedre, mangler du ikke noget sj\xe6ldent og kostbart til din lille skattejagt? |" },
	{ 55, "Det lader til, at \xe6rkebiskop Lazarus \xe6ggede mange af byens m\xe6nd til at drage ind i labyrinten for at finde kongens forsvundne s\xf8n. Han spillede p\xe5 deres frygt og piskede dem op til en rasende hob. Ingen af dem var beredt p\xe5, hvad der l\xe5 i den kolde jord... Lazarus forlod dem dernede - efterladt i un\xe6vnelige r\xe6""dslers kl\xf8""er - til at d\xf8. |" },
	{ 56, "Ja, Farnham har mumlet noget om en kolossal slagsbror, der svang et frygteligt v\xe5""ben. Jeg mener, han kaldte ham en slagter. |" },
	{ 57, "Ved Lyset, jeg kender denne nedrige d\xe6mon. Mange bar arene fra hans vrede p\xe5 deres kroppe, da de f\xe5 overlevende fra angrebet anf\xf8rt af Lazarus kravlede ud af katedralen. Jeg ved ikke, hvad han brugte til at spr\xe6tte sine ofre op, men det kunne ikke v\xe6re af denne verden. Det efterlod s\xe5r, der bet\xe6ndtes af sygdom, og selv jeg fandt dem n\xe6sten umulige at behandle. Vogt dig, hvis du agter at k\xe6mpe mod denne dj\xe6vel... |" },
	{ 58, "Da Farnham sagde noget om en slagter, der dr\xe6""bte folk, afviste jeg det straks. Men nu hvor du n\xe6vner det, er det m\xe5ske sandt. |" },
	{ 59, "Jeg s\xe5 det, Farnham kalder Slagteren, da den banede sig vej gennem mine venners kroppe. Han svang en fl\xe6kkekniv stor som en \xf8kse, hug lemmer af og f\xe6ldede tapre m\xe6nd, hvor de stod. Jeg blev skilt fra k\xe6mpen af en flok sm\xe5 skrigende d\xe6moner og fandt p\xe5 en eller anden m\xe5""de trappen ud. Jeg s\xe5 aldrig det gr\xe6sselige b\xe6st igen, men dets blodplettede \xe5syn hjems\xf8ger mig den dag i dag. |" },
	{ 60, "Stor! Stor fl\xe6kkekniv dr\xe6""ber alle mine venner. Kunne ikke standse ham, m\xe5tte l\xf8""be, kunne ikke redde dem. Fanget i et rum med s\xe5 mange lig... s\xe5 mange venner... |" },
	{ 61, "Slagteren er et sadistisk v\xe6sen, der fryder sig over andres tortur og smerte. Du har set hans h\xe5ndv\xe6rk p\xe5 drukkenbolten Farnham. Hans tilintetg\xf8relse vil g\xf8re meget for denne landsbys sikkerhed. |" },
	{ 62, "Jeg ved mere, end du skulle tro, om den gr\xe6sselige dj\xe6vel. Hans sm\xe5 venner fik fat i mig og n\xe5""ede mit ben, f\xf8r Griswold trak mig op af det hul. \n \nJeg siger det ligeud - dr\xe6""b ham, f\xf8r han dr\xe6""ber dig og f\xf8jer dit lig til sin samling. |" },
	{ 63, "H\xf8r p\xe5 mig, jeg beder dig. \xc6rkebiskop Lazarus f\xf8rte os herned for at finde den forsvundne prins. Slynglen f\xf8rte os i en f\xe6lde! Nu er alle d\xf8""de... dr\xe6""bt af en d\xe6mon, han kaldte Slagteren. H\xe6vn os! Find denne Slagter og dr\xe6""b ham, s\xe5 vore sj\xe6le endelig kan finde hvile... |" },
	{ 65, "Du fremsiger et interessant vers, skrevet i en stil, der minder mig om andre v\xe6rker. Lad mig t\xe6nke - hvad var det nu?\n \n...M\xf8rket indhyller de Skjulte. \xd8jne gl\xf8""der usete, kun lyden af barberkl\xf8""er, der kortvarigt skraber, piner de arme sj\xe6le, som er gjort blinde for al evighed. F\xe6ngslet for de s\xe5ledes ford\xf8mte kaldes De Blindes Haller... |" },
	{ 66, "Jeg har aldrig brudt mig meget om poesi. En sj\xe6lden gang hyrede jeg spillem\xe6nd, n\xe5r kroen gik godt, men det synes s\xe5 l\xe6nge siden nu. \n \nHvad? \xc5h, ja... \xf8h, du kunne vel h\xf8re, hvad andre ved. |" },
	{ 67, "Dette virker bekendt p\xe5 en eller anden m\xe5""de. Jeg mener at have l\xe6st noget meget lig det digt, da jeg studerede d\xe6moniske lidelsers historie. Det talte om et sted af stort onde, som... vent - du har vel ikke t\xe6nkt dig at tage derhen? |" },
	{ 68, "Har du sp\xf8rgsm\xe5l om blindhed, b\xf8r du tale med Pepin. Jeg ved, han gav min bedstemor en drik, der klarede hendes syn, s\xe5 m\xe5ske kan han ogs\xe5 hj\xe6lpe dig. |" },
	{ 69, "Jeg har desv\xe6rre hverken h\xf8rt om eller set et sted, der svarer til din levende beskrivelse, min ven. M\xe5ske kan fort\xe6lleren Cain v\xe6re til hj\xe6lp. |" },
	{ 70, "Se her... det er ret sjovt, ikke? Fatter du den? Blind - se her? |" },
	{ 71, "Dette er et sted af stor kval og r\xe6""dsel, og s\xe5ledes tjener det sin herre vel. \n \nTr\xe6""d varsomt, ellers kan du selv komme til at blive meget l\xe6ngere, end du havde regnet med. |" },
	{ 72, "Lad os se, s\xe6lger jeg dig noget? Nej. Giver du mig penge for at fort\xe6lle om det her? Nej. Er du nu p\xe5 vej hen for at tale med fort\xe6lleren, der lever for den slags? Ja. |" },
	{ 73, "Du h\xe6vder at have talt med Lachdanan? Han var en stor helt i sin levetid. Lachdanan var en h\xe6""derlig og retf\xe6rdig mand, der tjente sin konge trofast i mange \xe5r. Men det ved du naturligvis allerede.\n \nAf dem, der blev fanget i kongens forbandelse, ville Lachdanan v\xe6re den mindst tilb\xf8jelige til at underkaste sig m\xf8rket uden kamp, s\xe5 din beretning kunne godt v\xe6re sand. Var jeg i dit sted, min ven, ville jeg finde en m\xe5""de at befri ham fra hans pinsel. |" },
	{ 74, "Du taler om en tapper kriger, der l\xe6ngst er d\xf8""d! Jeg vil ikke h\xf8re den slags snak om samtaler med afd\xf8""de sj\xe6le i min krog\xe5rd, mange tak. |" },
	{ 75, "En gylden eliksir, siger du. Jeg har aldrig brygget en drik i den farve f\xf8r, s\xe5 jeg kan ikke sige, hvordan den ville virke, hvis du drak den. Som din healer r\xe5""der jeg dig indtr\xe6ngende: finder du en s\xe5""dan eliksir, s\xe5 g\xf8r som Lachdanan beder om, og pr\xf8v IKKE at bruge den. |" },
	{ 76, "Jeg har aldrig h\xf8rt om nogen Lachdanan. Beklager, men jeg tror ikke, jeg kan v\xe6re til megen hj\xe6lp. |" },
	{ 77, "Hvis det virkelig er Lachdanan, du har m\xf8""dt, s\xe5 r\xe5""der jeg dig til at hj\xe6lpe ham. Jeg havde med ham at g\xf8re flere gange og fandt ham \xe6rlig og loyal af natur. Forbandelsen, der ramte kong Leorics f\xf8lgesvende, ville ramme netop ham s\xe6rligt h\xe5rdt. |" },
	{ 78, " Lachdanan er d\xf8""d. Det ved alle, og du narrer mig ikke til at tro andet. Man kan ikke tale med de d\xf8""de. Det ved jeg! |" },
	{ 79, "Du kan m\xf8""de folk, der er fanget i labyrinten, s\xe5som Lachdanan. \n \nJeg fornemmer \xe6re og stor skyld i ham. Hj\xe6lp ham, og du hj\xe6lper hele Tristram. |" },
	{ 80, "Vent, lad mig g\xe6tte. Cain blev slugt af en v\xe6ldig kl\xf8""ft, der \xe5""bnede sig under ham. Han blev br\xe6ndt op i en kugle af helvedesild og kan ikke svare p\xe5 dine sp\xf8rgsm\xe5l mere. N\xe5, var det ikke det, der skete? S\xe5 k\xf8""ber du vel noget, eller ogs\xe5 g\xe5r du videre. |" },
	{ 81, "Dr\xe6""b mig ikke, jeg beder dig, h\xf8r mig f\xf8rst. Jeg var engang kaptajn for kong Leorics riddere og h\xe5ndh\xe6vede dette lands love med retf\xe6rd og \xe6re. S\xe5 faldt hans m\xf8rke forbandelse over os for den rolle, vi spillede i hans tragiske d\xf8""d. Mens mine ridderbr\xf8""dre bukkede under for deres forvredne sk\xe6""bne, flygtede jeg fra kongens gravkammer og s\xf8gte en m\xe5""de at befri mig fra forbandelsen. Det mislykkedes...\n \nJeg har h\xf8rt om en gylden eliksir, der kunne h\xe6ve forbandelsen og lade min sj\xe6l finde hvile, men jeg har ikke kunnet finde den. Min styrke svinder nu, og med den det sidste af min menneskelighed. Hj\xe6lp mig og find eliksiren. Jeg vil geng\xe6lde din indsats - det sv\xe6rger jeg p\xe5 min \xe6re. |" },
	{ 82, "Du har ikke fundet den gyldne eliksir. Jeg frygter, at jeg er ford\xf8mt for evigt. Bliv ved at pr\xf8ve, jeg beder dig... |" },
	{ 83, "Du har frelst min sj\xe6l fra ford\xf8mmelse, og derfor st\xe5r jeg i g\xe6ld til dig. Findes der nogensinde en m\xe5""de, hvorp\xe5 jeg kan geng\xe6lde dig fra den anden side af graven, vil jeg finde den, men indtil da - tag min hjelm. P\xe5 den rejse, jeg nu skal ud p\xe5, f\xe5r jeg ringe brug for den. M\xe5 den beskytte dig mod de m\xf8rke kr\xe6""fter dernede. G\xe5 med Lyset, min ven... |" },
	{ 84, "Griswold taler om Raseriets Ambolt - et sagnomspundet artefakt, l\xe6nge efters\xf8gt, men aldrig fundet. Sk\xe5ret af Barberkl\xf8""ftens d\xe6moners metalliske knogler blev Raseriets Ambolt smeltet omkring kranierne af underverdenens fem m\xe6gtigste magikere. Indgraveret med runer af magt og kaos vil ethvert v\xe5""ben eller enhver rustning, der smedes p\xe5 denne ambolt, blive s\xe6nket ned i Kaos' rige og gennemsyret af magiske egenskaber. Det siges, at Kaos' uforudsigelige natur g\xf8r det sv\xe6rt at vide, hvad udfaldet af smedearbejdet bliver... |" },
	{ 85, "Tror du ikke, Griswold ville v\xe6re en bedre at sp\xf8rge om dette? Han er ret fingernem, ved du. |" },
	{ 86, "Havde du s\xf8gt oplysninger om Helbredelsens Morter eller Renselsens S\xf8lvkalk, kunne jeg have hjulpet dig, min ven. Men i denne sag er du bedre tjent med at tale med enten Griswold eller Cain. |" },
	{ 87, "Griswolds far fortalte nogle af os, da vi var b\xf8rn, om en k\xe6mpe ambolt, der blev brugt til at lave m\xe6gtige v\xe5""ben. Han sagde, at n\xe5r en hammer ramte denne ambolt, rystede jorden af et v\xe6ldigt raseri. Hver gang jorden bev\xe6ger sig, mindes jeg den historie. |" },
	{ 88, "V\xe6r hilset! Det er altid en forn\xf8jelse at se en af mine bedste kunder! Jeg ved, at du er tr\xe6ngt dybere ned i labyrinten, og der er en historie, jeg har f\xe5""et fortalt, som nok er v\xe6rd at lytte til...\n \nEn af m\xe6ndene, der vendte tilbage fra labyrinten, fortalte mig om en mystisk ambolt, han st\xf8""dte p\xe5 under sin flugt. Hans beskrivelse mindede mig om sagn fra min ungdom om den br\xe6ndende Helvedessmedje, hvor m\xe6gtige magiske v\xe5""ben skabes. Sagnet lod, at dybt i Helvedessmedjen hvilede Raseriets Ambolt! Denne ambolt rummede selve den d\xe6moniske underverdens essens...\n \nDet siges, at ethvert v\xe5""ben smedet p\xe5 den br\xe6ndende ambolt fyldes med stor kraft. Er denne ambolt virkelig Raseriets Ambolt, kan jeg m\xe5ske smede dig et v\xe5""ben, der kan besejre selv Helvedes m\xf8rkeste herre! \n \nFind ambolten til mig, s\xe5 g\xe5r jeg i gang! |" },
	{ 89, "Intet endnu, hvad? N\xe5, bliv ved at lede. Et v\xe5""ben smedet p\xe5 ambolten kunne v\xe6re dit bedste h\xe5""b, og jeg er sikker p\xe5, at jeg kan lave dig et af sagnomspundne dimensioner. |" },
	{ 90, "Jeg kan n\xe6sten ikke tro det! Dette er Raseriets Ambolt - godt arbejde, min ven. Nu skal vi vise de slyngler, at der ingen v\xe5""ben findes i Helvede mere d\xf8""dbringende end dem, mennesker har smedet! Tag dette, og m\xe5 Lyset beskytte dig. |" },
	{ 91, "Griswold kan ikke s\xe6lge sin ambolt. Hvad skulle han s\xe5 g\xf8re? Og jeg ville ogs\xe5 blive vred, hvis nogen tog min ambolt! |" },
	{ 92, "Der findes mange artefakter i labyrinten, som rummer kr\xe6""fter hinsides d\xf8""deliges fatteevne. Nogle af dem b\xe6rer en fantastisk magt, der kan bruges af b\xe5""de Lyset og M\xf8rket. At sikre ambolten fra dybet kunne vende Syndekrigens gang mod Lyset. |" },
	{ 93, "Fandt du det artefakt til Griswold, kunne det l\xe6gge en ordentlig d\xe6mper p\xe5 min forretning her. \xc5rh, du finder det alligevel aldrig. |" },
	{ 94, "Blodets Port og Ildens Haller er kendem\xe6rker af mystisk oprindelse. Hvor end bogen, du l\xe6ser fra, h\xf8rer hjemme, er det med sikkerhed et sted af stor magt.\n \nSagn taler om en piedestal, hugget af obsidian, med en dam af kogende blod p\xe5 sin knoglebesatte flade. Der hentydes ogs\xe5 til Blodsten, som vil \xe5""bne en d\xf8r, der vogter en \xe6ldgammel skat...\n \nSkattens natur er hyllet i gisninger, min ven, men det siges, at oldtidshelten Arkaine gemte den hellige rustning Tapperhed i en hemmelig hv\xe6lving. Arkaine var den f\xf8rste d\xf8""delige, der vendte Syndekrigens gang og jog m\xf8rkets legioner tilbage til de Br\xe6ndende Helveder.\n \nLige f\xf8r Arkaine d\xf8""de, blev hans rustning gemt bort i en hemmelig hv\xe6lving. Det siges, at n\xe5r denne hellige rustning atter beh\xf8ves, vil en helt rejse sig og b\xe6re Tapperhed p\xe5 ny. M\xe5ske er du den helt... |" },
	{ 95, "Ethvert barn h\xf8rer historien om krigeren Arkaine og hans mystiske rustning kaldet Tapperhed. Kunne du finde dens hvilested, ville du v\xe6re godt beskyttet mod det onde i labyrinten. |" },
	{ 96, "Hmm... det lyder som noget, jeg burde huske, men jeg har haft s\xe5 travlt med at l\xe6re nye kure og lave bedre eliksirer, at jeg m\xe5 have glemt det. Beklager... |" },
	{ 97, "Historien om den magiske rustning kaldet Tapperhed h\xf8rte jeg tit drengene tale om. Du m\xe5 hellere sp\xf8rge en af m\xe6ndene i landsbyen. |" },
	{ 98, "Rustningen kendt som Tapperhed kunne v\xe6re det, der tipper v\xe6gtsk\xe5len til din fordel. Jeg kan fort\xe6lle dig, at mange har ledt efter den - inklusive mig selv. Arkaine gemte den godt, min ven, og der skal mere end en smule held til at l\xf8se de hemmeligheder, der har holdt den skjult i alle disse \xe5r. |" },
	{ 99, "Zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz... |" },
	{ 100, "Finder du disse Blodsten, s\xe5 brug dem med omhu. \n \nVejen er fuld af farer, og dit eneste h\xe5""b hviler i din tro p\xe5 dig selv. |" },
	{ 101, "Du agter at finde rustningen kendt som Tapperhed? \n \nIngen har nogensinde regnet ud, hvor Arkaine gemte sagerne, og n\xe5r mine kontakter ikke kunne finde den, tvivler jeg st\xe6rkt p\xe5, at du nogensinde g\xf8r. |" },
	{ 102, "Jeg kender kun \xe9t sagn, der taler om en kriger som den, du beskriver. Hans historie findes i Syndekrigens \xe6ldgamle kr\xf8niker...\n \nPlettet af tusind \xe5rs krig, blod og d\xf8""d st\xe5r Blodets Krigsherre p\xe5 et bjerg af sine s\xf8nderrevne ofre. Hans m\xf8rke klinge skriger en sort forbandelse mod de levende; en pint indbydelse til enhver, der ville st\xe5 foran denne Helvedes b\xf8""ddel.\n \nDet st\xe5r ogs\xe5 skrevet, at sk\xf8nt han engang var en d\xf8""delig, der k\xe6mpede ved M\xf8rkets Legions side under Syndekrigen, mistede han sin menneskelighed til sin um\xe6ttelige hunger efter blod. |" },
	{ 103, "Jeg har desv\xe6rre intet h\xf8rt om en s\xe5 grusom kriger, gode mester. Jeg h\xe5""ber ikke, du skal k\xe6mpe mod ham, for han lyder overordentlig farlig. |" },
	{ 104, "Cain ville kunne fort\xe6lle dig meget mere om den slags, end jeg nogensinde \xf8nsker at vide. |" },
	{ 105, "Skal du k\xe6mpe mod en s\xe5 frygtelig modstander, m\xe5 Lyset da v\xe6re din vejleder og dit v\xe6rn. Jeg vil have dig i mine tanker. |" },
	{ 106, "M\xf8rke og onde sagn omg\xe6rder Blodets Krigsherre. V\xe6r vel beredt, min ven, for han viser hverken n\xe5""de eller sk\xe5nsel. |" },
	{ 107, "Skal du altid tale om blod? Hvad med blomster og solskin og den k\xf8nne pige, der bringer drikkevarerne? H\xf8r her, min ven - du er besat, ved du det? |" },
	{ 108, "Hans f\xe6rdighed med klingen er frygtindgydende, og han har levet i tusinder af \xe5r uden at kende andet end krig. Beklager... jeg kan ikke se, om du vil besejre ham. |" },
	{ 109, "Jeg har aldrig handlet med denne krigsherre, du taler om, men det lyder, som om han slider mange sv\xe6rd op. Ville ikke have noget imod at forsyne hans h\xe6re... |" },
	{ 110, "Min klinge synger efter dit blod, d\xf8""delige, og ved mine m\xf8rke herrer skal den ikke n\xe6gtes det. |" },
	{ 111, "Griswold taler om Himmelstenen, der var bestemt for enklaven mod \xf8st. Den skulle bringes dertil for n\xe6rmere studier. Denne sten gl\xf8""dede med en energi, der p\xe5 en eller anden vis gav et syn ud over, hvad et almindeligt menneske kan besidde. Jeg ved ikke, hvilke hemmeligheder den rummer, min ven, men at finde denne sten ville givet vise sig s\xe6rdeles v\xe6rdifuldt. |" },
	{ 112, "Karavanen standsede her for at tage forsyninger med p\xe5 rejsen mod \xf8st. Jeg solgte dem et helt udvalg af frisk frugt og noget fortrinligt s\xf8""dbr\xf8""d, Garda lige havde bagt. Skam, hvad der skete med dem... |" },
	{ 113, "Jeg ved ikke, hvad det var, de troede, de kunne se med den sten, men \xe9t vil jeg sige: falder der sten ned fra himlen, m\xe5 man hellere passe p\xe5! |" },
	{ 114, "Nuvel, en karavane med nogle meget fornemme folk standsede her, men det er et godt stykke tid siden. De havde s\xe6lsomme accenter og skulle ud p\xe5 en lang rejse, s\xe5 vidt jeg husker. \n \nJeg ser ikke, hvordan du kan h\xe5""be at finde noget af det, de f\xf8rte med sig. |" },
	{ 115, "Bliv et \xf8jeblik - jeg har en historie, du m\xe5ske finder interessant. En karavane p\xe5 vej mod de \xf8stlige kongeriger drog her igennem for nogen tid siden. Den skulle efter sigende b\xe6re et stykke af himlen, som var faldet til jorden! Karavanen blev overfaldet af kappekl\xe6""dte ryttere lige nord herfor langs vejen. Jeg gennems\xf8gte vraggodset efter denne himmelsten, men den var ingen steder at finde. Skulle du finde den, tror jeg, at jeg kan lave noget nyttigt af den. |" },
	{ 116, "Jeg venter stadig p\xe5, at du bringer mig den sten fra himlen. Jeg ved, at jeg kan lave noget m\xe6gtigt af den. |" },
	{ 117, "Lad mig se den - ja... ja, det er, som jeg troede. Giv mig et \xf8jeblik...\n \nSe her. Jeg har sat stykker af stenen i en s\xf8lvring, min far efterlod mig. Jeg h\xe5""ber, den tjener dig vel. |" },
	{ 118, "Jeg havde engang en fin ring; den var rigtig dyr, med bl\xe5t og gr\xf8nt og r\xf8""dt og s\xf8lv. Husker dog ikke, hvad der blev af den. Jeg savner virkelig den ring... |" },
	{ 119, "Himmelstenen er meget m\xe6gtig, og var det nogen anden end Griswold, der bad dig finde den, ville jeg hindre det. Han vil t\xe6mme dens kr\xe6""fter, og dens brug bliver til gavn for os alle. |" },
	{ 120, "Hvis nogen kan lave noget ud af den sten, er det Griswold. Han ved, hvad han g\xf8r, og hvor meget jeg end pr\xf8ver at stj\xe6le hans kunder, respekterer jeg kvaliteten af hans arbejde. |" },
	{ 121, "Heksen Adria s\xf8ger en sort svamp? Jeg ved lige s\xe5 meget om sorte svampe som om r\xf8""de sild. M\xe5ske kan healeren Pepin fort\xe6lle dig mere, men dette er noget, der ikke findes i nogen af mine historier eller b\xf8ger. |" },
	{ 122, "Lad mig blot sige dette: hverken Garda eller jeg ville nogensinde, NOGENSINDE servere sorte svampe for vore \xe6rede g\xe6ster. Vil Adria have svampe i sin gryde, er det hendes sag, men jeg kan ikke hj\xe6lpe dig med at finde nogen. Sorte svampe... modbydeligt! |" },
	{ 123, "Heksen fortalte mig, at du ledte efter en d\xe6monhjerne for at hj\xe6lpe mig med at skabe min eliksir. Den skulle blive af stor v\xe6rdi for de mange, der s\xe5res af de gr\xe6sselige b\xe6ster, hvis jeg blot kan l\xf8se de hemmeligheder, jeg formoder, dens alkymi rummer. Kan du fjerne hjernen fra en d\xe6mon, n\xe5r du dr\xe6""ber den, ville jeg v\xe6re taknemmelig, om du bragte mig den. |" },
	{ 124, "Fortrinligt, det var lige, hvad jeg havde i tankerne. Jeg n\xe5""ede at g\xf8re eliksiren f\xe6rdig uden denne, men det kan ikke skade at have den at studere. Vil du bringe dette til heksen? Jeg tror, hun venter det. |" },
	{ 125, "Jeg tror, Ogden har nogle svampe i k\xe6lderen. Hvorfor sp\xf8rger du ikke ham? |" },
	{ 126, "Hvis Adria ikke har en af disse, kan du v\xe6re vis p\xe5, at det er noget sj\xe6ldent. Mere hj\xe6lp kan jeg ikke tilbyde, men det lyder som... en enorm, gigantisk, opsvulmet, oppustet svamp! N\xe5, god jagt, m\xe5 man vel sige. |" },
	{ 127, "Ogden blander en H\xc5RD sort svamp, men jeg bliver syg af at drikke den. H\xf8r, h\xf8r... her er hemmeligheden - m\xe5""dehold er sagen! |" },
	{ 128, "Hvad har vi her? Interessant, det ligner en bog om reagenser. Hold \xf8jnene \xe5""bne efter en sort svamp. Den burde v\xe6re temmelig stor og let at kende. Finder du den, s\xe5 bring mig den, ikke? |" },
	{ 129, "Det er en stor, sort svamp, jeg beh\xf8ver. Af sted nu og hent den til mig, s\xe5 jeg kan bruge den i en s\xe6rlig bryg, jeg arbejder p\xe5. |" },
	{ 130, "Ja, denne bliver perfekt til en bryg, jeg er ved at skabe. For resten leder healeren efter hjernen fra en eller anden d\xe6mon, s\xe5 han kan behandle dem, der er ramt af deres giftige edder. Jeg tror, han agter at lave en eliksir af den. Hj\xe6lper du ham med at finde, hvad han beh\xf8ver, s\xe5 se, om du kan skaffe mig en pr\xf8ve af eliksiren. |" },
	{ 131, "Hvorfor bringer du den herhen? Jeg har ingen brug for en d\xe6monhjerne for tiden. Jeg beh\xf8ver noget af den eliksir, healeren arbejder p\xe5. Han beh\xf8ver det groteske organ, du holder, og bring mig s\xe5 eliksiren. Enkelt, n\xe5r man t\xe6nker over det, ikke? |" },
	{ 132, "Hvad? Nu bringer du mig den eliksir fra healeren? Jeg n\xe5""ede at g\xf8re min bryg f\xe6rdig uden den. Behold du den bare... |" },
	{ 133, "Jeg har ingen svampe i nogen st\xf8rrelse eller farve til salg. Hvad med noget lidt mere nyttigt? |" },
	{ 134, "hing" },
	{ 135, "Vores tid er ved at rinde ud! Jeg fornemmer hans m\xf8rke kraft vokse, og kun du kan hindre ham i at n\xe5 sin fulde styrke. |" },
	{ 136, "Jeg er vis p\xe5, at du gjorde dit bedste, men jeg frygter, at selv din styrke og vilje m\xe5ske ikke r\xe6kker. Diablo er nu p\xe5 h\xf8jden af sin jordiske magt, og du f\xe5r brug for alt dit mod og al din kraft for at besejre ham. M\xe5 Lyset beskytte og lede dig, min ven. Jeg vil hj\xe6lpe p\xe5 enhver m\xe5""de, jeg form\xe5r. |" },
	{ 137, "Hvis heksen ikke kan hj\xe6lpe dig og foresl\xe5r, at du ops\xf8ger Cain, hvad f\xe5r dig s\xe5 til at tro, at jeg skulle vide noget? Det lyder som en meget alvorlig sag. Du b\xf8r skynde dig hen til fort\xe6lleren, som Adria foresl\xe5r. |" },
	{ 138, "Jeg kan ikke f\xe5 meget ud af skriften p\xe5 dette kort, men m\xe5ske kan Adria eller Cain hj\xe6lpe dig med at tyde, hvad det henviser til. \n \nJeg kan se, at det er et kort over stjernerne p\xe5 vores himmel, men mere end det ligger uden for mine evner. |" },
	{ 139, "Den bedste at sp\xf8rge om den slags ville v\xe6re vores fort\xe6ller. \n \nCain er meget kyndig i \xe6ldgamle skrifter, og det er let det \xe6ldste stykke papir, jeg nogensinde har set. |" },
	{ 140, "Jeg har aldrig set et kort af den slags f\xf8r. Hvor har du det fra? Sk\xf8nt jeg ingen anelse har om, hvordan det l\xe6ses, kan Cain eller Adria m\xe5ske give dig de svar, du s\xf8ger. |" },
	{ 141, "H\xf8r her, kom t\xe6ttere p\xe5. Jeg ved ikke, om du ved, hvad jeg ved, men du har virkelig fat i noget her. Det er et kort. |" },
	{ 142, "\xc5h, jeg frygter, at dette slet ikke lover godt. Dette stjernekort varsler stor ulykke, men dets hemmeligheder er ikke mine at fort\xe6lle. Tiden er inde til, at du f\xe5r en meget alvorlig samtale med fort\xe6lleren... |" },
	{ 143, "Jeg har ledt efter et kort, men det d\xe9r er det bestemt ikke. Du burde vise det til Adria - hun kan sikkert fort\xe6lle dig, hvad det er. \xc9t vil jeg sige: det ser gammelt ud, og gammelt betyder som regel v\xe6rdifuldt. |" },
	{ 144, "Vaaaer s\xf8""d, ikke g\xf8r ondt. Ikke dr\xe6""b. Lad leve, og n\xe6ste gang godt bringer til dig. |" },
	{ 145, "Noget til dig jeg laver. Igen, ikke dr\xe6""b Gharbad. Lev og giv godt. \n \nDu tag dette som bevis jeg holder ord... |" },
	{ 146, "Intet endnu! N\xe6sten f\xe6rdig. \n \nMeget m\xe6gtigt, meget st\xe6rkt. Lev! Lev! \n \nIngen smerte og l\xf8""fte jeg holder! |" },
	{ 147, "Denne for god til dig. Meget m\xe6gtig! Du vil have - du tag! |" },
	{ 148, "Hvad?! Hvorfor er du her? Alle disse afbrydelser er nok til at drive en til vanvid. Her, tag dette og lad mig arbejde. Forstyr mig ikke mere! |" },
	{ 149, "Arrrrgh! Din nysgerrighed bliver din d\xf8""d!!! |" },
	{ 150, "Goddag, min ven. Bliv en stund og lyt... |" },
	{ 151, "N\xe5r du tr\xe6nger dybere ned i labyrinten, kan du finde folianter af stor visdom gemt dernede. \n \nL\xe6s dem grundigt, for de kan fort\xe6lle dig ting, som selv jeg ikke kan. |" },
	{ 152, "Jeg kender mange myter og sagn, der kan rumme svar p\xe5 sp\xf8rgsm\xe5l, som m\xe5tte opst\xe5 p\xe5 dine f\xe6rd i labyrinten. St\xf8""der du p\xe5 udfordringer og sp\xf8rgsm\xe5l, du s\xf8ger viden om, s\xe5 ops\xf8g mig, og jeg vil fort\xe6lle, hvad jeg kan. |" },
	{ 153, "Griswold - en mand af stor handling og stort mod. Han har sikkert aldrig fortalt dig om dengang, han gik ind i labyrinten for at redde Wirt, vel? Han kender sin del af farerne dernede, men det g\xf8r du jo ogs\xe5. Han er en dygtig h\xe5ndv\xe6rker, og p\xe5st\xe5r han at kunne hj\xe6lpe dig p\xe5 nogen m\xe5""de, kan du regne med hans \xe6rlighed og hans kunnen. |" },
	{ 154, "Ogden har ejet og drevet kroen Den Opg\xe5""ende Sol i n\xe6sten fire \xe5r nu. Han k\xf8""bte den blot f\xe5 m\xe5neder, f\xf8r alting her gik ad helvede til. Han og hans kone Garda har ikke penge til at rejse, for de satte alt, hvad de ejede, i at skabe sig et liv her. Han er en god mand med en dyb ansvarsf\xf8lelse. |" },
	{ 155, "Stakkels Farnham. Han er en foruroligende p\xe5mindelse om det ford\xf8mte f\xf8lge, der gik ind i katedralen med Lazarus den m\xf8rke dag. Han slap fra det med livet, men hans mod og en stor del af hans forstand blev efterladt i et m\xf8rkt hul. Han finder nu om dage kun tr\xf8st p\xe5 bunden af sit krus, men der ligger af og til stumper af sandhed begravet i hans evindelige vr\xf8vl. |" },
	{ 156, "Heksen Adria er noget for sig her i Tristram. Hun kom kort efter, at katedralen blev vanhelliget, mens de fleste andre flygtede. Hun fik bygget en lille hytte i udkanten af byen, tilsyneladende p\xe5 \xe9n nat, og har adgang til mange s\xe6lsomme og arkane artefakter og videnfolianter, som selv jeg aldrig har set f\xf8r. |" },
	{ 157, "Historien om Wirt er skr\xe6mmende og tragisk. Han blev revet ud af sin mors arme og sl\xe6""bt ned i labyrinten af de sm\xe5, gr\xe6sselige d\xe6moner, der svinger onde spyd. Mange andre b\xf8rn blev taget den dag, deriblandt kong Leorics s\xf8n. Slottets riddere gik derned, men vendte aldrig tilbage. Smeden fandt drengen, men f\xf8rst efter at de gr\xe6sselige b\xe6ster var begyndt at pine ham for deres sadistiske forn\xf8jelse. |" },
	{ 158, "Ah, Pepin. Jeg regner ham for en sand ven - m\xe5ske den n\xe6rmeste, jeg har her. Han er til tider lidt forvirret, men en mere omsorgsfuld og bet\xe6nksom sj\xe6l har aldrig eksisteret. Hans viden og evner har f\xe5 lige, og hans d\xf8r st\xe5r altid \xe5""ben. |" },
	{ 159, "Gillian er en fin kvinde. H\xf8jt elsket for sit gode hum\xf8r og sin lette latter har hun en s\xe6rlig plads i mit hjerte. Hun bliver p\xe5 kroen for at fors\xf8rge sin gamle bedstemor, der er for syg til at rejse. Jeg frygter til tider for hendes sikkerhed, men jeg ved, at enhver mand i landsbyen hellere ville d\xf8 end se hende komme til skade. |" },
	{ 160, "V\xe6r hilset, gode mester. Velkommen til kroen Den Opg\xe5""ende Sol! |" },
	{ 161, "Mange eventyrere har prydet bordene i min kro, og ti gange s\xe5 mange historier er fortalt over lige s\xe5 meget \xf8l. Det eneste, jeg nogensinde h\xf8rte dem alle enes om, var denne gamle sandhed. M\xe5ske kan den hj\xe6lpe dig: Du kan sk\xe6re i k\xf8""det, men du m\xe5 knuse knoglen. |" },
	{ 162, "Smeden Griswold er s\xe6rdeles kyndig i v\xe5""ben og rustninger. F\xe5r du nogensinde brug for at f\xe5 arbejdet p\xe5 dit grej, er han absolut manden at ops\xf8ge. |" },
	{ 163, "Farnham tilbringer alt for megen tid her og drukner sine sorger i billig \xf8l. Jeg ville smide ham ud, men han led nu s\xe5 meget under sin tid i labyrinten. |" },
	{ 164, "Adria er vis ud over sine \xe5r, men jeg m\xe5 indr\xf8mme - hun skr\xe6mmer mig en smule. \n \nN\xe5, lige meget. Har du nogensinde brug for at handle med trolddomsvarer, driver hun en s\xe6lsomt velassorteret hytte lige p\xe5 den anden side af floden. |" },
	{ 165, "Vil du vide mere om vores landsbys historie, ved fort\xe6lleren Cain en hel del om fortiden. |" },
	{ 166, "Wirt er en gavtyv og en lille slyngel. Han rendte altid ind i problemer, og det er ingen overraskelse, hvad der skete med ham. \n \nHan har nok drevet om et sted, hvor han ikke burde have v\xe6ret. Jeg har ondt af drengen, men jeg billiger ikke det selskab, han holder.  |" },
	{ 167, "Pepin er en god mand - og uden tvivl den gavmildeste i landsbyen. Han tager sig altid af andres behov, men problemer af den ene eller anden slags synes at f\xf8lge ham, hvor end han g\xe5r... |" },
	{ 168, "Gillian, min krostuepige? Var det ikke for hendes pligtf\xf8lelse over for sin bedstemor, var hun flygtet herfra for l\xe6nge siden. \n \nGud skal vide, at jeg tryglede hende om at rejse og sagde, at jeg ville se efter den gamle kone, men hun er for s\xf8""d og omsorgsfuld til at have gjort det. |" },
	{ 169, "Hvad fejler du, min ven? |" },
	{ 170, "Jeg har gjort en meget interessant opdagelse. I mods\xe6tning til os kan v\xe6snerne i labyrinten hele sig selv uden hj\xe6lp fra drikke eller magi. S\xe5rer du et af monstrene, s\xe5 s\xf8rg for, at det er d\xf8""dt, ellers kan det meget vel gendanne sig selv. |" },
	{ 171, "F\xf8r katedralen blev overtaget af, ja, hvad end der lurer dernede, var den et sted for stor l\xe6rdom. Der findes mange b\xf8ger d\xe9r. Finder du nogen, b\xf8r du l\xe6se dem alle, for nogle kan rumme hemmeligheder om labyrintens virke. |" },
	{ 172, "Griswold ved lige s\xe5 meget om krigskunst, som jeg ved om l\xe6gekunst. Han er en snu k\xf8""bmand, men hans arbejde overg\xe5s af ingen. N\xe5 ja, det er vel ogs\xe5, fordi han er den eneste smed tilbage her. |" },
	{ 173, "Cain er en sand ven og en vis mand. Han holder et v\xe6ldigt bibliotek og har en medf\xf8""dt evne til at sk\xf8nne mange tings sande natur. Har du nogensinde sp\xf8rgsm\xe5l, er han manden at g\xe5 til. |" },
	{ 174, "Selv mine evner har ikke kunnet hele Farnham helt. Ak, jeg har kunnet lappe hans krop, men hans sind og \xe5nd ligger uden for alt, hvad jeg form\xe5r. |" },
	{ 175, "Sk\xf8nt jeg bruger visse begr\xe6nsede former for magi til at skabe de drikke og eliksirer, jeg opbevarer her, er Adria en sand troldkvinde. Hun synes aldrig at sove, og hun har altid adgang til mange mystiske folianter og artefakter. Jeg tror, hendes hytte kan v\xe6re langt mere end det skur, den ligner, men jeg kan aldrig komme indenfor. |" },
	{ 176, "Stakkels Wirt. Jeg gjorde alt, hvad der var muligt for barnet, men jeg ved, at han afskyr det tr\xe6""ben, jeg blev n\xf8""dt til at s\xe6tte p\xe5 hans ben. Hans s\xe5r var gr\xe6sselige. Ingen - og slet ikke et s\xe5 lille barn - burde lide, som han gjorde. |" },
	{ 177, "Jeg forst\xe5r virkelig ikke, hvorfor Ogden bliver her i Tristram. Han lider af en let nerv\xf8sitet, men han er en klog og flittig mand, der ville klare sig godt, hvor end han tog hen. Det er vel frygten for de mange mord, der sker p\xe5 egnen omkring os, eller m\xe5ske hans kones \xf8nsker, der holder ham og hans familie, hvor de er. |" },
	{ 178, "Ogdens krostuepige er en s\xf8""d pige. Hendes bedstemor er ganske syg og lider af vrangforestillinger. \n \nHun h\xe6vder, at det er syner, men jeg har intet bevis, hverken for eller imod. |" },
	{ 179, "Goddag! Hvordan kan jeg st\xe5 til tjeneste? |" },
	{ 180, "Min bedstemor dr\xf8mte, at du ville komme og tale med mig. Hun har syner, ved du, og kan se ind i fremtiden. |" },
	{ 181, "Kvinden i udkanten af byen er en heks! Hun virker s\xf8""d nok, og hendes navn, Adria, klinger smukt i \xf8ret, men jeg er meget bange for hende. \n \nDer skal en, der er ganske modig, som dig, til at se, hvad hun laver derude. |" },
	{ 182, "Vores smed er en stolthed for Tristrams folk. Han er ikke blot en mesterh\xe5ndv\xe6rker, der har vundet mange konkurrencer i sit lav, han fik ogs\xe5 ros af selveste kong Leoric - m\xe5 hans sj\xe6l hvile i fred. Griswold er ogs\xe5 en stor helt; sp\xf8rg bare Cain. |" },
	{ 183, "Cain har v\xe6ret Tristrams fort\xe6ller, s\xe5 l\xe6nge jeg kan huske. Han ved s\xe5 meget og kan fort\xe6lle dig stort set alt om n\xe6sten alting. |" },
	{ 184, "Farnham er en drukkenbolt, der fylder sin mave med \xf8l og alle andres \xf8rer med vr\xf8vl. \n \nJeg ved, at b\xe5""de Pepin og Ogden har medynk med ham, men jeg bliver s\xe5 fortvivlet af at se ham glide l\xe6ngere og l\xe6ngere ned i omt\xe5get sl\xf8vhed hver aften. |" },
	{ 185, "Pepin reddede min bedstemors liv, og det kan jeg aldrig geng\xe6lde ham. Hans evne til at hele enhver sygdom er m\xe6gtigere end det st\xe6rkeste sv\xe6rd og mere g\xe5""defuld end nogen formular, du kan n\xe6vne. F\xe5r du nogensinde brug for helbredelse, kan Pepin hj\xe6lpe dig. |" },
	{ 186, "Jeg voksede op med Wirts mor, Canace. Sk\xf8nt hun kun kom let til skade, da de gr\xe6sselige v\xe6sner stjal ham, kom hun sig aldrig. Jeg tror, hun d\xf8""de af et knust hjerte. Wirt er blevet en ondskabsfuld kn\xe6gt, der kun s\xf8ger at tjene p\xe5 andres sved. Jeg ved, at han har lidt og set r\xe6""dsler, jeg ikke engang kan forestille mig, men noget af det m\xf8rke h\xe6nger stadig over ham. |" },
	{ 187, "Ogden og hans kone har taget mig og min bedstemor ind i deres hjem og lader mig endda tjene et par guldstykker ved at arbejde p\xe5 kroen. Jeg skylder dem s\xe5 meget og h\xe5""ber en dag at forlade dette sted og hj\xe6lpe dem med at starte et fint hotel i \xf8st. |" },
	{ 188, "N\xe5, hvad kan jeg g\xf8re for dig? |" },
	{ 189, "Leder du efter et godt v\xe5""ben, s\xe5 lad mig vise dig dette. Tag dit almindelige stumpe v\xe5""ben, s\xe5som en stridsk\xf8lle. Virker som en dr\xf8m mod de fleste af de ud\xf8""de r\xe6""dsler dernede, og intet er bedre til at splintre tynde sm\xe5 skeletter! |" },
	{ 190, "\xd8ksen? Ja, det er et godt v\xe5""ben, afbalanceret mod enhver fjende. Se, hvordan den kl\xf8ver luften, og forestil dig s\xe5 et dejligt fedt d\xe6monhoved i dens bane. Husk dog, at den er langsom at svinge - men sikke et tungt slag, den giver! |" },
	{ 191, "Se den \xe6g, den balance. Et sv\xe6rd i de rette h\xe6nder, og mod den rette fjende, er alle v\xe5""bens mester. Dens skarpe klinge finder ikke meget at hugge eller stikke i p\xe5 de ud\xf8""de, men mod en levende, \xe5ndende fjende sk\xe6rer et sv\xe6rd bedre i k\xf8""det! |" },
	{ 192, "Dine v\xe5""ben og din rustning vil b\xe6re m\xe6rker af dine kampe mod M\xf8rket. Bringer du dem til mig, kan jeg med lidt arbejde og en varm esse s\xe6tte dem i fineste kampstand igen. |" },
	{ 193, "Mens jeg n\xe6rmest m\xe5 smugle de metaller og redskaber ind, jeg beh\xf8ver, fra karavaner, der kredser om vores forbandede by, synes den heks, Adria, altid at f\xe5 fat i, hvad hun beh\xf8ver. Vidste jeg blot den mindste smule om at t\xe6mme magi, som hun g\xf8r, kunne jeg lave i sandhed utrolige ting. |" },
	{ 194, "Gillian er en rar pige. Skam, at hendes bedstemor har s\xe5 svagt et helbred, ellers ville jeg s\xf8rge for at f\xe5 dem begge herfra med en af handelskaravanerne. |" },
	{ 195, "Somme tider synes jeg, Cain taler for meget, men det er vel hans kald i livet. Kunne jeg b\xf8je st\xe5l lige s\xe5 godt, som han kan b\xf8je dit \xf8re, kunne jeg smede en hofrustning fin nok til en kejser! |" },
	{ 196, "Jeg var med Farnham den nat, Lazarus f\xf8rte os ind i labyrinten. Jeg s\xe5 aldrig \xe6rkebiskoppen igen, og jeg havde m\xe5ske ikke overlevet, hvis ikke Farnham havde v\xe6ret ved min side. Jeg frygter, at angrebet gjorde hans sj\xe6l lige s\xe5 leml\xe6stet som, ja, et andet gjorde mit ben. Jeg kan ikke k\xe6mpe denne kamp for ham nu, men jeg ville, hvis jeg kunne. |" },
	{ 197, "En god mand, der s\xe6tter andres behov over sine egne. Du finder ingen tilbage i Tristram - eller noget andet sted for den sags skyld - der har et ondt ord at sige om healeren. |" },
	{ 198, "Den kn\xe6gt ender i alvorlige problemer... eller jeg burde vel sige, igen. Jeg har fors\xf8gt at f\xe5 ham interesseret i at arbejde her og l\xe6re et \xe6rligt h\xe5ndv\xe6rk, men han foretr\xe6kker de h\xf8je fortjenester ved at handle med varer af tvivlsom oprindelse. Jeg kan ikke bebrejde ham det efter det, der skete med ham, men jeg ville \xf8nske, han i det mindste var forsigtig. |" },
	{ 199, "Kroejeren har ringe forretning og ingen rigtig m\xe5""de at tjene p\xe5. Han f\xe5r det til at l\xf8""be rundt ved at give mad og logi til dem, der en sj\xe6lden gang driver gennem landsbyen, men de stikker lige s\xe5 gerne af i natten, som de betaler. Havde det ikke v\xe6ret for de lagre af korn og t\xf8rret k\xf8""d, han holdt i sin k\xe6lder, ja, s\xe5 var de fleste af os sultet ihjel det f\xf8rste \xe5r, da hele egnen var l\xf8""bet over ende af d\xe6moner. |" },
	{ 200, "Kan en mand ikke f\xe5 lov at drikke i fred? |" },
	{ 201, "Pigen, der bringer drikkevarerne? \xc5h ja, sikke en k\xf8n dame. Og s\xe5 s\xf8""d. |" },
	{ 202, "Hvorfor g\xf8r den gamle heks ikke noget til en forandring? Jo, jo, hun har sager, men h\xf8r p\xe5 mig... hun er unaturlig. Jeg har aldrig set hende spise eller drikke - og man kan ikke stole p\xe5 nogen, der ikke drikker bare en lille smule. |" },
	{ 203, "Cain er ikke den, han siger, han er. Jo, jo, han fort\xe6ller en god historie... nogle af dem er rigtig uhyggelige eller sjove... men jeg tror, han ved mere, end han ved, han ved. |" },
	{ 204, "Griswold? Gode gamle Griswold. Jeg elsker ham som en bror! Vi k\xe6mpede sammen, ved du, dengang... vi... Lazarus... Lazarus... Lazarus!!! |" },
	{ 205, "Hehehe, jeg kan lide Pepin. Han pr\xf8ver virkelig, ved du. H\xf8r her, du skulle s\xf8rge for at l\xe6re ham at kende. S\xe5""dan en god fyr, og folk vil altid have hj\xe6lp. Hov, det ville vel v\xe6re lidt ligesom dig, hvad, helt? Jeg var ogs\xe5 en helt engang... |" },
	{ 206, "Wirt er en kn\xe6gt med flere problemer end selv mig, og jeg ved alt om problemer. H\xf8r her - den kn\xe6gt har en fed aftale, men han har v\xe6ret dernede, ved du? Mistede et ben! M\xe5 g\xe5 rundt p\xe5 et stykke tr\xe6. S\xe5 trist, s\xe5 trist... |" },
	{ 207, "Ogden er den bedste mand i byen. Jeg tror ikke, hans kone kan lide mig s\xe6rlig godt, men s\xe5 l\xe6nge hun bliver ved at tappe t\xf8nder, kan jeg fint lide hende. Jeg har vist tilbragt mere tid med Ogden end de fleste, men han er s\xe5 god ved mig... |" },
	{ 208, "Jeg vil fort\xe6lle dig noget, for jeg ved alt om det her. Det er mit speciale. Det her er den bedste... deeeen bedste! Den anden \xf8l duer ikke, siden de dumme hunde... |" },
	{ 209, "Ingen h\xf8... h\xf8rer nogensinde p\xe5 mig. Et sted - jeg er ikke helt sikker - men et sted under kirken ligger en hel bunke guld. Gl\xf8""dende og skinnende og bare venter p\xe5, at nogen henter den. |" },
	{ 210, "Jeg ved godt, du har dine egne ideer, og jeg ved, du ikke vil tro det her, men det v\xe5""ben, du har der - det duer bare ikke mod de store b\xf8ller! \xc5h, jeg er ligeglad med, hvad Griswold siger, de kan ikke lave noget, som de kunne i gamle dage... |" },
	{ 211, "Hvis jeg var dig... og det er jeg ikke... men hvis jeg var, ville jeg s\xe6lge alt det, du har, og komme v\xe6k herfra. Den kn\xe6gt derude... han har altid noget godt, men du m\xe5 give ham lidt guld, ellers viser han dig ikke engang, hvad han har. |" },
	{ 212, "Jeg fornemmer en sj\xe6l p\xe5 jagt efter svar... |" },
	{ 213, "Visdom fortjenes, den gives ikke. Opdager du en foliant af viden, s\xe5 fort\xe6r dens ord. Kender du allerede de arkane mysterier, der er nedf\xe6ldet i en bog, s\xe5 husk - det mesterskab kan altid vokse. |" },
	{ 214, "Den st\xf8rste kraft er ofte den kortest levede. Du kan finde \xe6ldgamle magtord skrevet p\xe5 pergamentruller. Disse rullers styrke ligger i, at b\xe5""de l\xe6rling og mester kan kaste dem med samme evne. Deres svaghed er, at de f\xf8rst m\xe5 l\xe6ses h\xf8jt og aldrig kan holdes parat i dit sind. Vid ogs\xe5, at disse ruller kun kan l\xe6ses \xe9n gang, s\xe5 brug dem med omhu. |" },
	{ 215, "Sk\xf8nt solens hede er uden m\xe5l, er et stearinlys' blotte flamme en st\xf8rre fare. Ingen energier, hvor store de end er, kan bruges uden det rette fokus. For mange formularer kan fortryllede stave lades med magiske energier mange gange. Jeg har evnen til at genoprette deres kraft - men vid, at intet g\xf8res uden en pris. |" },
	{ 216, "Summen af vores viden ligger i summen af dens folk. Finder du en bog eller et relikvie, du ikke kan tyde, s\xe5 t\xf8v ikke med at bringe det til mig. Kan jeg f\xe5 mening ud af det, deler jeg, hvad jeg finder. |" },
	{ 217, "For en mand, der kun kender jern, findes ingen st\xf8rre magi end st\xe5l. Smeden Griswold er mere troldmand, end han selv ved. Hans evne til at forene ild og metal har ingen lige i dette land. |" },
	{ 218, "Ford\xe6rvelse har bedragets styrke, men uskyld rummer renhedens kraft. Den unge kvinde Gillian har et rent hjerte og s\xe6tter sin bedstemors behov over sine egne. Hun frygter mig, men kun fordi hun ikke forst\xe5r mig. |" },
	{ 219, "En kiste \xe5""bnet i m\xf8rke rummer ingen st\xf8rre skat, end n\xe5r den \xe5""bnes i lyset. Fort\xe6lleren Cain er en g\xe5""de, men kun for dem, der ikke ser efter. Hans viden om, hvad der ligger under katedralen, er langt st\xf8rre, end selv han tillader sig at indse. |" },
	{ 220, "Jo h\xf8jere du s\xe6tter din tro p\xe5 \xe9n mand, desto l\xe6ngere har den at falde. Farnham har mistet sin sj\xe6l, men ikke til nogen d\xe6mon. Den gik tabt, da han s\xe5 sine bysb\xf8rn forr\xe5""dt af \xe6rkebiskop Lazarus. Der er viden at hente hos ham, men du m\xe5 skille kendsgerning fra fantasi. |" },
	{ 221, "H\xe5nden, hjertet og sindet kan udrette mirakler, n\xe5r de er i fuldkommen harmoni. Healeren Pepin ser ind i kroppen p\xe5 en m\xe5""de, som selv jeg ikke kan. Hans evne til at genoprette de syge og s\xe5rede forst\xe6rkes af hans forst\xe5""else for eliksirer og drikke. Han er s\xe5 stor en forbundsf\xe6lle, som du har i Tristram. |" },
	{ 222, "Der er meget om fremtiden, vi ikke kan se, men n\xe5r den kommer, er det b\xf8rnene, der b\xe6rer den. Drengen Wirt har en sorthed over sin sj\xe6l, men han udg\xf8r ingen trussel mod byen eller dens folk. Hans hemmelighedsfulde handler med gadeb\xf8rn og un\xe6vnte lav i n\xe6rliggende byer giver ham adgang til mange sager, der ikke let findes i Tristram. Sk\xf8nt hans metoder kan dadles, kan Wirt yde hj\xe6lp i din kamp mod det fremrykkende M\xf8rke. |" },
	{ 223, "Jordv\xe6gge og str\xe5tag g\xf8r ikke et hjem. Kroejeren Ogden tjener et st\xf8rre form\xe5l i denne by, end mange forst\xe5r. Han giver husly til Gillian og hendes bedstemor, holder det liv, Farnham har tilbage, oppe og er et anker for alle, der er tilbage i byen, til det Tristram, der engang var. Hans kro, og de enkle gl\xe6""der der stadig findes der, giver et glimt af et liv, folk her husker. Det er det minde, der stadig n\xe6rer deres h\xe5""b om din sejr. |" },
	{ 224, "Pssst... herovre... |" },
	{ 225, "Ikke alle i Tristram har brug for - eller et marked for - alt, hvad du finder i labyrinten. Ikke engang mig, hvor sv\xe6rt det end er at tro. \n \nSomme tider er det kun dig, der kan finde et form\xe5l med visse ting. |" },
	{ 226, "Stol ikke p\xe5 alt, hvad drukkenbolten siger. For mange \xf8l har sl\xf8ret hans syn og hans sunde fornuft. |" },
	{ 227, "Hvis du ikke har bem\xe6rket det, k\xf8""ber jeg intet fra Tristram. Jeg er import\xf8r af kvalitetsvarer. Vil du s\xe6lge skrammel, m\xe5 du g\xe5 til Griswold, Pepin eller den heks, Adria. De snupper sikkert, hvad end du kan bringe dem... |" },
	{ 228, "Jeg skylder vel smeden mit liv - hvad der er tilbage af det. Jo, Griswold tilb\xf8""d mig en l\xe6replads i smedjen, og han er fin nok, men jeg f\xe5r aldrig penge nok til at... n\xe5, lad os bare sige, at jeg har bestemte planer, der kr\xe6ver en stor m\xe6ngde guld. |" },
	{ 229, "Var jeg et par \xe5r \xe6ldre, ville jeg overose hende med alle de rigdomme, jeg kunne skrabe sammen, og tro mig, jeg kan f\xe5 fingre i nogle rigtig fine sager. Gillian er en smuk pige, der burde komme v\xe6k fra Tristram, s\xe5 snart det er sikkert. Hmmm... m\xe5ske tager jeg hende med, n\xe5r jeg rejser... |" },
	{ 230, "Cain ved for meget. Han skr\xe6mmer livet af mig - endnu mere end kvinden p\xe5 den anden side af floden. Han bliver ved at fort\xe6lle mig, hvor heldig jeg er at v\xe6re i live, og at min historie er forudsagt i sagn. Jeg tror, han er g\xe5""et fra forstanden. |" },
	{ 231, "Farnham - d\xe9r har du en mand med alvorlige problemer, og jeg ved alt om, hvor alvorlige problemer kan v\xe6re. Han stolede for meget p\xe5 \xe9n mands h\xe6""derlighed, og Lazarus f\xf8rte ham lige i d\xf8""dens gab. \xc5h, jeg ved, hvordan der er dernede, s\xe5 begynd ikke at fort\xe6lle mig om dine planer om at udrydde det onde i labyrinten. Pas bare p\xe5 dine ben... |" },
	{ 232, "S\xe5 l\xe6nge du ikke skal have noget syet p\xe5 igen, er gamle Pepin s\xe5 god som nogen. \n \nHavde jeg haft nogle af de drikke, han brygger, havde jeg m\xe5ske stadig haft mit ben... |" },
	{ 233, "Adria bekymrer mig virkelig. Jo, Cain er uhyggelig med det, han kan fort\xe6lle om fortiden, men den heks kan se ind i DIN fortid. Hun har ogs\xe5 altid en m\xe5""de at skaffe, hvad hun beh\xf8ver. Adria f\xe5r fingre i flere varer, end jeg har set passere gennem portene til kongens basar under h\xf8jfesten. |" },
	{ 234, "Ogden er et fjols, fordi han bliver her. Jeg kunne f\xe5 ham ud af byen for en meget rimelig pris, men han insisterer p\xe5 at f\xe5 det til at k\xf8re med den dumme kro. Han giver da i det mindste Gillian et sted at arbejde, og hans kone Garda laver en fortrinlig k\xf8""dpostej... |" },
	{ 235, "Hinsides Heltenes Hal ligger Knoglekammeret. Evig d\xf8""d venter enhver, der s\xf8ger at stj\xe6le de skatte, der er sikret i dette rum. S\xe5 taler R\xe6""dslens Herre, og s\xe5 st\xe5r det skrevet. |" },
	{ 236, "...og s\xe5ledes, l\xe5st bag Blodets Port og forbi Ildens Hal, venter Tapperhed p\xe5, at Lysets Helt skal v\xe5gne... |" },
	{ 237, "Jeg ser det, du ej f\xe5r at se.\nSynet m\xe6lket, \xf8jne d\xf8r.\nVender du dig, er de v\xe6k,\nhviskende deres skjulte sang.\nDa ser du det, der ej kan v\xe6re,\nskygger g\xe5r, hvor lys b\xf8r st\xe5.\nUd af m\xf8rket, ud af sind,\nst\xf8""dt ned i De Blindes Haller. |\n" },
	{ 238, "Helvedes v\xe5""benkamre er hjem for Blodets Krigsherre. I hans k\xf8lvand ligger tusinders leml\xe6stede kroppe. Engle s\xe5vel som mennesker er m\xe6jet ned for at fuldbyrde hans endel\xf8se ofringer til de M\xf8rke, der skriger efter \xe9n ting - blod. |" },
	{ 239, "Hinsides Heltenes Hal ligger Knoglekammeret. Evig d\xf8""d venter enhver, der s\xf8ger at stj\xe6le de skatte, der er sikret i dette rum. S\xe5 taler R\xe6""dslens Herre, og s\xe5 st\xe5r det skrevet. |" },
	{ 240, "...og s\xe5ledes, l\xe5st bag Blodets Port og forbi Ildens Hal, venter Tapperhed p\xe5, at Lysets Helt skal v\xe5gne... |" },
	{ 241, "Jeg ser det, du ej f\xe5r at se.\nSynet m\xe6lket, \xf8jne d\xf8r.\nVender du dig, er de v\xe6k,\nhviskende deres skjulte sang.\nDa ser du det, der ej kan v\xe6re,\nskygger g\xe5r, hvor lys b\xf8r st\xe5.\nUd af m\xf8rket, ud af sind,\nst\xf8""dt ned i De Blindes Haller. |\n" },
	{ 242, "Helvedes v\xe5""benkamre er hjem for Blodets Krigsherre. I hans k\xf8lvand ligger tusinders leml\xe6stede kroppe. Engle s\xe5vel som mennesker er m\xe6jet ned for at fuldbyrde hans endel\xf8se ofringer til de M\xf8rke, der skriger efter \xe9n ting - blod. |" },
	{ 243, "Hinsides Heltenes Hal ligger Knoglekammeret. Evig d\xf8""d venter enhver, der s\xf8ger at stj\xe6le de skatte, der er sikret i dette rum. S\xe5 taler R\xe6""dslens Herre, og s\xe5 st\xe5r det skrevet. |" },
	{ 244, "...og s\xe5ledes, l\xe5st bag Blodets Port og forbi Ildens Hal, venter Tapperhed p\xe5, at Lysets Helt skal v\xe5gne... |" },
	{ 245, "Jeg ser det, du ej f\xe5r at se.\nSynet m\xe6lket, \xf8jne d\xf8r.\nVender du dig, er de v\xe6k,\nhviskende deres skjulte sang.\nDa ser du det, der ej kan v\xe6re,\nskygger g\xe5r, hvor lys b\xf8r st\xe5.\nUd af m\xf8rket, ud af sind,\nst\xf8""dt ned i De Blindes Haller. |\n" },
	{ 246, "Helvedes v\xe5""benkamre er hjem for Blodets Krigsherre. I hans k\xf8lvand ligger tusinders leml\xe6stede kroppe. Engle s\xe5vel som mennesker er m\xe6jet ned for at fuldbyrde hans endel\xf8se ofringer til de M\xf8rke, der skriger efter \xe9n ting - blod. |" },
	{ 249, "Giv agt og v\xe6r vidne til de sandheder, der ligger heri, for de er Horadrims sidste arv. En krig raser selv nu, hinsides de marker, vi kender - mellem de H\xf8je Himles utopiske kongeriger og de Br\xe6ndende Helveders kaotiske afgrunde. Denne krig kaldes Den Store Konflikt, og den har raset og br\xe6ndt l\xe6ngere end nogen stjerne p\xe5 himlen. Ingen side vinder overtaget l\xe6nge, mens Lysets og M\xf8rkets kr\xe6""fter uafladeligt k\xe6mper om herred\xf8mmet over hele skabelsen. |" },
	{ 250, "Giv agt og v\xe6r vidne til de sandheder, der ligger heri, for de er Horadrims sidste arv. N\xe5r Den Evige Konflikt mellem de H\xf8je Himle og de Br\xe6ndende Helveder falder p\xe5 d\xf8""delig jord, kaldes den Syndekrigen. Engle og d\xe6moner vandrer forkl\xe6""dt blandt menneskene og k\xe6mper i det skjulte, borte fra d\xf8""deliges nysgerrige blikke. Nogle dristige, m\xe6gtige d\xf8""delige har endda sluttet sig til den ene eller den anden side og v\xe6ret med til at forme Syndekrigens gang. |" },
	{ 251, "Giv agt og v\xe6r vidne til de sandheder, der ligger heri, for de er Horadrims sidste arv. For n\xe6sten tre hundrede \xe5r siden blev det kendt, at de Br\xe6ndende Helveders Tre \xd8verste Onder p\xe5 g\xe5""defuld vis var kommet til vores verden. De Tre Br\xf8""dre h\xe6rgede \xd8stens lande i \xe5rtier, mens menneskeheden sk\xe6lvede i deres k\xf8lvand. Vores orden - Horadrim - blev grundlagt af en kreds af hemmelighedsfulde magikere for at jage og fange de Tre Onder \xe9n gang for alle.\n \nDe oprindelige Horadrim fangede to af de Tre i m\xe6gtige artefakter kaldet Sj\xe6lesten og begravede dem dybt under de \xf8""de \xf8stlige sande. Det tredje Onde undgik tilfangetagelse og flygtede mod vest med mange af Horadrim i h\xe6lene. Det Tredje Onde - kendt som Diablo, R\xe6""dslens Herre - blev til sidst fanget, hans essens sat i en Sj\xe6lesten og begravet i denne labyrint.\n \nV\xe6r advaret: Sj\xe6lestenen m\xe5 holdes skjult for dem uden for troen. Blev Diablo sluppet fri, ville han s\xf8ge en krop, der er let at styre, da han ville v\xe6re meget svag - m\xe5ske en gammel mands eller et barns. |" },
	{ 252, "S\xe5ledes skete det, at der kom en stor omv\xe6ltning i de Br\xe6ndende Helveder, kendt som Det M\xf8rke Eksil. De Mindre Onder v\xe6ltede de Tre \xd8verste Onder og forviste deres \xe5ndeformer til de d\xf8""deliges rige. D\xe6monerne Belial (L\xf8gnens Herre) og Azmodan (Syndens Herre) k\xe6mpede om herred\xf8mmet over Helvede i de Tre Br\xf8""dres frav\xe6r. Hele Helvede delte sig mellem Belials og Azmodans fraktioner, mens de H\xf8je Himles styrker uafladeligt hamrede p\xe5 selve Helvedes Porte. |" },
	{ 253, "Mange d\xe6moner rejste til de d\xf8""deliges rige for at s\xf8ge de Tre Br\xf8""dre. Disse d\xe6moner blev fulgt til det d\xf8""delige plan af engle, der jagede dem gennem \xd8stens store byer. Englene allierede sig med en hemmelighedsfuld orden af d\xf8""delige magikere ved navn Horadrim, som hurtigt blev dygtige d\xe6monj\xe6gere. De skabte sig ogs\xe5 mange m\xf8rke fjender i underverdenerne. |" },
	{ 254, "S\xe5ledes skete det, at de Tre \xd8verste Onder blev forvist i \xe5ndeform til de d\xf8""deliges rige, og efter at have s\xe5""et kaos over \xd8sten i \xe5rtier blev de jaget ned af de d\xf8""delige Horadrims forbandede orden. Horadrim brugte artefakter kaldet Sj\xe6lesten til at indeslutte essensen af Mephisto, Hadets Herre, og hans bror Baal, \xd8""del\xe6ggelsens Herre. Den yngste bror - Diablo, R\xe6""dslens Herre - undslap mod vest.\n \nTil sidst fangede Horadrim ogs\xe5 Diablo i en Sj\xe6lesten og begravede ham under en \xe6ldgammel, glemt katedral. D\xe9r sover R\xe6""dslens Herre og venter... |" },
	{ 255, "Al pris til Diablo - R\xe6""dslens Herre og Det M\xf8rke Eksils Overlever. Da han v\xe5gnede af sin lange s\xf8vn, talte min Herre og Mester til mig om hemmeligheder, f\xe5 d\xf8""delige kender. Han fortalte, at de H\xf8je Himles kongeriger og de Br\xe6ndende Helveders afgrunde f\xf8rer en evig krig. Han \xe5""benbarede de kr\xe6""fter, der har bragt denne splid til menneskenes riger. Min herre har navngivet kampen om denne verden og alle, der lever her: Syndekrigen. |" },
	{ 256, "H\xe6""der og Lovprisning til Diablo - R\xe6""dslens Herre og De Tres Anf\xf8rer. Min Herre talte til mig om sine to br\xf8""dre, Mephisto og Baal, som blev forvist til denne verden for l\xe6nge siden. Min Herre \xf8nsker at afvente sin tid og samle sin frygtindgydende magt, s\xe5 han kan befri sine fangne br\xf8""dre fra deres grave under \xd8stens sande. N\xe5r min Herre slipper sine br\xf8""dre fri, skal Syndekrigen atter kende de Tres raseri. |" },
	{ 257, "Hil og Offer til Diablo - R\xe6""dslens Herre og Sj\xe6lenes \xd8""del\xe6gger. Da jeg v\xe6kkede min Mester af hans s\xf8vn, fors\xf8gte han at overtage en d\xf8""deligs skikkelse. Diablo fors\xf8gte at tage kong Leorics krop, men min Mester var for svag efter sit fangenskab. Min Herre beh\xf8vede et enkelt og uskyldigt anker til denne verden og fandt drengen Albrecht fuldkommen til opgaven. Mens den gode kong Leoric blev efterladt gal af Diablos mislykkede bes\xe6ttelse, bortf\xf8rte jeg hans s\xf8n Albrecht og bragte ham for min Mester. Jeg afventer nu Diablos kald og beder om at blive bel\xf8nnet, n\xe5r han endelig tr\xe6""der frem. |" },
	{ 258, "Gudskelov, du er vendt tilbage!\nMeget har \xe6ndret sig, siden du boede her, min ven. Alt var fredeligt, indtil de m\xf8rke ryttere kom og \xf8""delagde vores landsby. Mange blev m\xe6jet ned, hvor de stod, og de, der greb til v\xe5""ben, blev dr\xe6""bt eller sl\xe6""bt bort som slaver - eller v\xe6rre. Kirken i udkanten af byen er blevet vanhelliget og bruges til m\xf8rke ritualer. Skrigene, der giver genlyd i natten, er umenneskelige, men nogle af vore bysb\xf8rn kan endnu v\xe6re i live. F\xf8lg stien mellem min kro og smedens butik for at finde kirken og redde, hvem du kan. \n \nM\xe5ske kan jeg fort\xe6lle dig mere, hvis vi tales ved igen. Held og lykke.|" },
	{ 259, "Hinsides Heltenes Hal ligger Knoglekammeret. Evig d\xf8""d venter enhver, der s\xf8ger at stj\xe6le de skatte, der er sikret i dette rum. S\xe5 taler R\xe6""dslens Herre, og s\xe5 st\xe5r det skrevet. |" },
	{ 260, "...og s\xe5ledes, l\xe5st bag Blodets Port og forbi Ildens Hal, venter Tapperhed p\xe5, at Lysets Helt skal v\xe5gne... |" },
	{ 261, "Jeg ser det, du ej f\xe5r at se.\nSynet m\xe6lket, \xf8jne d\xf8r.\nVender du dig, er de v\xe6k,\nhviskende deres skjulte sang.\nDa ser du det, der ej kan v\xe6re,\nskygger g\xe5r, hvor lys b\xf8r st\xe5.\nUd af m\xf8rket, ud af sind,\nst\xf8""dt ned i De Blindes Haller. |\n" },
	{ 262, "Helvedes v\xe5""benkamre er hjem for Blodets Krigsherre. I hans k\xf8lvand ligger tusinders leml\xe6stede kroppe. Engle s\xe5vel som mennesker er m\xe6jet ned for at fuldbyrde hans endel\xf8se ofringer til de M\xf8rke, der skriger efter \xe9n ting - blod. |" },
	{ 263, "Hinsides Heltenes Hal ligger Knoglekammeret. Evig d\xf8""d venter enhver, der s\xf8ger at stj\xe6le de skatte, der er sikret i dette rum. S\xe5 taler R\xe6""dslens Herre, og s\xe5 st\xe5r det skrevet. |" },
	{ 264, "...og s\xe5ledes, l\xe5st bag Blodets Port og forbi Ildens Hal, venter Tapperhed p\xe5, at Lysets Helt skal v\xe5gne... |" },
	{ 265, "Jeg ser det, du ej f\xe5r at se.\nSynet m\xe6lket, \xf8jne d\xf8r.\nVender du dig, er de v\xe6k,\nhviskende deres skjulte sang.\nDa ser du det, der ej kan v\xe6re,\nskygger g\xe5r, hvor lys b\xf8r st\xe5.\nUd af m\xf8rket, ud af sind,\nst\xf8""dt ned i De Blindes Haller. |\n" },
	{ 266, "Helvedes v\xe5""benkamre er hjem for Blodets Krigsherre. I hans k\xf8lvand ligger tusinders leml\xe6stede kroppe. Engle s\xe5vel som mennesker er m\xe6jet ned for at fuldbyrde hans endel\xf8se ofringer til de M\xf8rke, der skriger efter \xe9n ting - blod. |" },
	{ 267, "Du m\xe5 for enhver pris tilintetg\xf8re de to d\xe6moner, Horazon har fanget i sit Sanktum! Skulle de undslippe deres fangenskab, vil de skabe en forbindelse til denne verden, der f\xe5r det, der ligger under katedralen, til at ligne et eventyr for b\xf8rn. |" },
	{ 268, "Sandelig en dristig fort\xe6lling! Min begr\xe6nsede tid under katedralen g\xf8r mig d\xe5rligt rustet til at hj\xe6lpe dig med dette, men som altid finder du Cain velbevandret i sagn og folketro. |" },
	{ 269, "Horazon var vanvittig! Der findes kr\xe6""fter, man ikke blander sig i! Det ville ikke undre mig, om du kun fandt de forkullede rester af det forbandede fjols! |" },
	{ 270, "0-crimson.TRN" },
	{ 271, "Det lyder sandelig som m\xf8rke v\xe6sner. Jeg er uvidende om den slags sager, men jeg vil formode, at vores fort\xe6ller kender til den slags sagn. |" },
	{ 272, "S\xe5 du s\xf8ger viden om Helvedes krige, g\xf8r du? Kryptiske folianter taler om store slag, der afgjorde, hvilke d\xe6monherrer der skulle herske over Helvede. De n\xe6vner ogs\xe5 en bitter rivalisering mellem to af disse herrer - Azmodan, der f\xf8rte Den Hornede D\xf8""d mod lysets h\xe6re, og Belial, kendt som L\xf8gnens Herre. Deres had til hinanden er evigt, grundene til deres afsky - tabt selv for dem selv. \n \nDer g\xe5r frasagn om, at den gale troldmand Horazon p\xe5 en eller anden vis fangede disse to helvedesherrers l\xf8jtnanter i sit sanktum. D\xe9r sidder de stadig... |" },
	{ 273, "Du vil jage en d\xe6mon, var det, hvad du sagde? Jeg ved, jeg ikke h\xf8rte det, for ingen jager d\xe6moner, nej. Ingen! |" },
	{ 274, "Et skattekort? Har du det p\xe5 dig? Lad mig se! Hmm, det ser temmelig gammelt ud, og nogle af bygningerne i byen er ikke p\xe5 kortet. \xc5h, gid jeg kunne g\xe5 med og lede efter skatten, men jeg skal snart p\xe5 arbejde. |" },
	{ 275, "Pasning og fodring af d\xe6moner er absolut IKKE noget, der interesserer mig. Her er et venligt r\xe5""d: f\xe5r du chancen, s\xe5 dr\xe6""b ALT, hvad du ser dernede. |" },
	{ 276, "0-crimson.TRN" },
	{ 277, "S\xe5 du er helten, alle taler om. M\xe5ske kunne du hj\xe6lpe en fattig, j\xe6vn bonde ud af en frygtelig knibe? I kanten af min frugthave, lige syd herfor, svulmer en gr\xe6sselig ting op af jorden! Jeg kan ikke komme til mine afgr\xf8""der eller mine h\xf8""baller, og mine stakkels k\xf8""er vil sulte. Heksen gav mig denne og sagde, at den ville spr\xe6nge tingesten ud af min mark. Kunne du \xf8""del\xe6gge den, ville jeg v\xe6re evigt taknemmelig. Jeg ville selv g\xf8re det, men nogen m\xe5 jo blive her hos k\xf8""erne...|" },
	{ 278, "Farmer's speech from HF is unused now" },
	{ 279, "Er den v\xe6k? Sendte du den tilbage til de m\xf8rke afkroge af Hades, der udkl\xe6kkede den? Du hvad? \xc5h nej, sig ikke, at du har tabt den! S\xe5""danne sager er ikke billige, skal jeg sige dig. Du m\xe5 finde den og s\xe5 spr\xe6nge det uhyre ud af vores by.|" },
	{ 280, "Jeg h\xf8rte eksplosionen helt herfra! Mange tak, venlige fremmede. Med alle de ting, der kommer op af jorden, monstre der overtager kirken og s\xe5 videre, er det pr\xf8vende tider. Jeg er kun en fattig bonde, men her - tag dette med min store tak.|" },
	{ 281, "Ak, s\xe5""dan en knibe jeg er i... m\xe5ske... Nej, jeg kunne ikke bebyrde dig, med alle de andre genvordigheder. M\xe5ske n\xe5r du har renset kirken for nogle af de v\xe6sner, kunne du komme tilbage... og afse lidt tid til at hj\xe6lpe en fattig bonde?|" },
	{ 282, "Jeg har virkelig ikke tid til at tale om et kort, du leder efter. Jeg har mange syge, der beh\xf8ver min hj\xe6lp, og din med for den sags skyld.|" },
	{ 283, "Jeg har mistet Theo! Jeg har mistet min bedste ven! Vi legede nede ved floden, og Theo sagde, han ville hen og se p\xe5 den store gr\xf8nne ting. Jeg sagde, vi ikke skulle, men vi sneg os derover, og s\xe5 kom der pludselig et KRYB frem! Vi l\xf8""b v\xe6k, men Theo faldt, og krybet GREB ham og tog ham med!|" },
	{ 284, "Fandt du ham? Du M\xc5 finde Theodore, jeg beder dig! Han er kun lille. Han kan ikke klare sig selv! V\xe6r s\xf8""d!|" },
	{ 285, "Du fandt ham! Du fandt ham! Tak! \xc5h Theo, skr\xe6mte de v\xe6mmelige kryb dig? Hov! Adr! Der sidder noget fast i din pels! F\xf8j! Kom, Theo, lad os g\xe5 hjem! Tak igen, helteperson!|" },
	{ 286, "L\xe6nge har vi ligget i dvale, og tiden til at v\xe5gne er kommet. Efter vores lange s\xf8vn er vi fyldt af stor hunger. Snart, nu, skal vi \xe6""de...|" },
	{ 287, "Har du moret dig, lille pattedyr? Hvor ynkeligt. Din lille verden bliver slet ingen udfordring.|" },
	{ 288, "Disse lande skal besudles, og vort afkom skal oversv\xf8mme de marker, mennesker kalder hjem. Vore f\xf8letr\xe5""de skal omslutte denne verden, og vi vil t\xe6re p\xe5 dens beboeres k\xf8""d. Mennesket skal blive vort kv\xe6g og vor f\xf8""de.|" },
	{ 289, "Ah, jeg kan lugte dig... du er n\xe6r! N\xe6r! Ssss... duften af blod og frygt... hvor lokkende...|" },
	{ 296, "Om forladelse, men har du h\xf8rt, hvad der sker? Nogle af m\xe6ndene er forsvundet fra landsbyen. Dicas s\xf8nner, Inaius og Ruphe, p\xe5st\xe5r at have set s\xe6lsomme lys gl\xf8""de dybt inde i skoven for nogle dage siden, men ingen har h\xf8rt fra dem siden. Jeg har ogs\xe5 selv set et karmoisinr\xf8""dt flimmer bag askelundene, men jeg har v\xe6ret for bange til at n\xe6rme mig. Jeg frygter, at Ogden eller vores healer Pepin bliver de n\xe6ste. Vil du ikke nok finde ud af, hvad der er sket? |" },
	{ 297, "Har du unders\xf8gt, hvad de s\xe6lsomme lys skyldes, endnu? Flere m\xe6nd er forsvundet, siden vi sidst taltes ved, og jeg begynder at frygte, at vi snart alle forsvinder. |" },
	{ 298, "Jeg m\xe5 indr\xf8mme, at jeg ogs\xe5 har set disse s\xe6lsomme lys, men jeg har ikke f\xf8lt mig draget mod dem. Jeg skal nok holde mig fra dem, og jeg vil r\xe5""de enhver, der kommer her, til at g\xf8re det samme. |" },
	{ 299, "Ruphe og Inaius er forsvundet? Lyset bevare os! Findes der intet sikkert sted? Vores eneste h\xe5""b om at vende tilbage til et fredeligt liv hviler p\xe5 dig. Jeg beder dig, find de drenge og bring dem hjem til deres familie. |" },
	{ 300, "Gode helt, et \xf8jeblik af din tid. Da jeg tils\xe5 en af byens folk, der var blevet ganske syg, bem\xe6rkede jeg noget s\xe6lsomt ved hans hjem. Der kom underlige lyde og en kvalmende s\xf8""dlig lugt op fra k\xe6lderen. I den tro at dampene m\xe5ske havde noget med hans sygdom at g\xf8re, unders\xf8gte jeg det. I hans k\xe6lder v\xe5ndede monstr\xf8se orme sig op fra undergrunden. Jeg b\xf8nfalder dig, dr\xe6""b disse v\xe6sner, f\xf8r de finder vej ind i byen. Jeg lod d\xf8ren til hans hus st\xe5 \xe5""ben for dig. Det er det over for mit. |" },
	{ 301, "Endnu en gang har du frelst denne ydmyge by fra det fremtr\xe6ngende onde. Vi st\xe5r som altid i evig g\xe6ld til dig. |" },
	{ 302, "Jeg frygter, at ormene snart kan oversv\xf8mme landsbyen! Jeg ved, at de kommer op fra huset over for mit. Alene tanken om de slimede b\xe6ster, der siver ind i mit hus, g\xf8r mig d\xe5rlig. Jeg beder dig, befri os for dem. |" },
	{ 303, "Jeg har intet af den slags set i min butik, men jeg skal holde skarpt \xf8je med dem. Kommer de denne vej, bryder de sig nok ikke om ilden i min esse. |" },
	{ 304, "Orme, der stiger op af jorden? Mange af de \xe6ldgamle skrifter taler om giftige insekter og gr\xe6sselige v\xe6sner fra himlen og havet, der plager menneskeheden. Det er ingen overraskelse, at selve jorden nu byder p\xe5 en lignende fare, hvor underverdenens beboere er over os. |" },
	{ 305, "*brakker sig* \n \nH\xf8r, h\xf8r..\n \nJeg kan ikke engang lide orme.  \n \nFort\xe6l mig ikke om dine orme!  \n \nJeg vil ikke have dine orme!  \n \nN\xe6h, nej tak!  \n \nIngen orme til mig... |" },
	{ 306, "Ops\xf8g den bolig, healeren Pepin har vist dig til. D\xe9r vil dine opgaver blive klare og dine midler \xe5""benbare. |" },
	{ 307, "Haha! Har de sat dig til at jage orme nu?  \nHvad bliver det n\xe6ste, at samle blade? Plukke svampe?  \n \nH\xf8r, min ven, du har en hel kirke fuld af d\xe6moner derovre at bekymre dig om. Jeg ser ikke, hvordan et par sm\xe5 orme kan v\xe6re s\xe5 slemme. |" },
	{ 308, "Det lyder temmelig modbydeligt, og jeg har desv\xe6rre intet h\xf8rt om nogen orme. M\xe5ske kan fort\xe6lleren Cain v\xe6re til hj\xe6lp. |" },
	{ 309, "Vent, f\xf8r du siger noget: min bedstemor havde en dr\xf8m med k\xe6mpestore, buglende v\xe6sner i. Hun s\xe5 ogs\xe5 Pepin l\xf8""be fra et hus i byen. Tror du, det betyder noget? |" },
	{ 310, "D\xf8""delige, befri mig fra mit fangenskab, og din bel\xf8nning bliver st\xf8rre, end du kan forestille dig. L\xe6s bogen, og jeg slippes fri.|" },
	{ 311, "Gillian er blevet ved og ved om s\xe6lsomme lys i tr\xe6""erne, men jeg har ikke kunnet f\xe5 hoved eller hale p\xe5 hendes historie. Jeg har bestemt ikke set nogen s\xe6lsomme lys, og gjorde jeg, ville de ikke v\xe6re min mindste bekymring. |" },
	{ 312, "Sk\xf8nt krostuepigen til tider kan virke lidt forvirret, er det sandt, at m\xe6nd forsvinder fra landsbyen. Det minder mig om \xe6ldgamle skrifter om en d\xe6monisk fristerinde kaldet Andariel. Kendt som Kvalens M\xf8 var hendes t\xf8rst efter d\xf8""deligt blod s\xe5 stor, at hun s\xf8gte at l\xe6re en formular til at bryde ind i de d\xf8""deliges rige. Ved at forf\xf8re en af underverdenens m\xf8rke troldm\xe6nd tog Andariel den viden, hun beh\xf8vede, og begyndte s\xe5 at lokke d\xf8""delige m\xe6nd ind i sit m\xf8rke hj\xf8rne af Helvede. Er disse sagn sande, er hun ikke et v\xe6sen, man skal tage let p\xe5... |" },
	{ 313, "*snork* |" },
	{ 314, "Ved du hvad, jeg har ledt efter de lys, men jeg kan ikke finde dem. Siger Gillian, de er der, s\xe5, \xf8h, tror jeg hende, men jeg mangler stadig at se dem selv. |" },
	{ 315, "Succubussen er en d\xe6mon, der t\xe6rer p\xe5 d\xf8""delige m\xe6nds essens. Du vil opdage, at Andariel har en god appetit. Byen bliver snart t\xf8mt for voksne m\xe6nd, hvis du ikke standser hendes \xe6""den nu. |" },
	{ 316, "D\xe6moner, der antager skikkelse af smukke kvinder, siger du? Det er forf\xe6rdeligt! Lyset v\xe6re lovet, at du l\xf8ste denne g\xe5""de, f\xf8r flere af vore m\xe6nd blev lokket i d\xf8""den. Tak, fordi du endnu en gang v\xe6rner os mod m\xf8rkets magter. |" },
	{ 317, "Jeg har fors\xf8gt formularer, trusler, besv\xe6rgelser og k\xf8""bslagning med dette gr\xe6sselige v\xe6sen - uden held. Mine metoder til at tr\xe6lbinde mindre d\xe6moner synes ingen virkning at have p\xe5 dette frygtelige b\xe6st.|" },
	{ 318, "Mit hjem ford\xe6rves langsomt af denne u\xf8nskede fanges nedrighed. Krypterne er\tfulde af skygger, der bev\xe6ger sig lige uden for mit synsfelt. Den svage skraben af kl\xf8""er danser i udkanten af min h\xf8relse. De leder, tror jeg, efter denne dagbog.|" },
	{ 319, "I sine rasen har v\xe6snet ladet sit navn slippe ud - Na-Krul. Jeg har fors\xf8gt at udforske navnet, men de mindre d\xe6moner har p\xe5 en eller anden vis \xf8""delagt mit bibliotek. Na-Krul... Navnet fylder mig med en kold gru. Jeg foretr\xe6kker at t\xe6nke p\xe5 det blot som V\xe6snet frem for at gruble over dets sande navn.|" },
	{ 320, "Det fangne v\xe6sens hyl af raseri holder mig fra den s\xf8vn, jeg s\xe5 h\xe5rdt beh\xf8ver. Det raser mod den, der sendte det til Tomrummet, og det nedkalder nedrige forbandelser over mig for at fange det her. Dets ord fylder mit hjerte med r\xe6""dsel, og dog kan jeg ikke lukke dets stemme ude.|" },
	{ 321, "Min tid rinder hastigt ud. Jeg m\xe5 nedf\xe6lde m\xe5""derne at sv\xe6kke d\xe6monen p\xe5 og derefter skjule teksten, s\xe5 hans h\xe5ndlangere ikke finder en m\xe5""de at bruge min viden til at befri deres herre. Jeg h\xe5""ber, at den, der finder denne dagbog, vil s\xf8ge den viden.|" },
	{ 322, "Den, der finder denne rulle, p\xe5l\xe6gges at standse det d\xe6moniske v\xe6sen, der ligger inden for disse mure. Min tid er omme. Selv nu kradser dets helvedes h\xe5ndlangere p\xe5 den skr\xf8""belige d\xf8r, jeg gemmer mig bag.  \n \nJeg har l\xe6nket d\xe6monen med arkan magi og indesluttet den bag store mure, men jeg frygter, det ikke er nok. \n \nFormularerne i mine tre grimoirer giver dig beskyttet adgang til hans rige, men kun hvis de kastes i den rette r\xe6kkef\xf8lge. H\xe5ndtagene ved indgangen fjerner barriererne og befrier d\xe6monen; r\xf8r dem ikke! Brug kun disse formularer til at komme ind, ellers kan hans magt blive for stor til, at du kan besejre ham.|" },
	{ 323, "In Spiritu Sanctum. |" },
	{ 324, "Praedictum Otium. |" },
	{ 325, "Efficio Obitus Ut Inimicus. |" },
	{ 326, "In Spiritu Sanctum. |" },
	{ 327, "Praedictum Otium. |" },
	{ 328, "Efficio Obitus Ut Inimicus. |" },
	{ 329, "In Spiritu Sanctum. |" },
	{ 330, "Praedictum Otium. |" },
	{ 331, "Efficio Obitus Ut Inimicus. |" },
	{ 332, "In Spiritu Sanctum. |" },
	{ 333, "Praedictum Otium. |" },
	{ 334, "Efficio Obitus Ut Inimicus. |" },
	{ 335, "In Spiritu Sanctum. |" },
	{ 336, "Praedictum Otium. |" },
	{ 337, "Efficio Obitus Ut Inimicus. |" },
	{ 338, "\\\"Belials l\xf8jtnant kendes som Grimspike...\n \nVogt dig for denne d\xe6mon, for hans styrke synes uden m\xe5l...\n \nAt l\xe6se denne rulle og dermed sige hans navn n\xe6r en arkan bindingscirkel vil med sikkerhed hidkalde ham dertil...\\\" |" },
	{ 339, "\\\"Belials l\xf8jtnant kendes som Grimspike...\n \nVogt dig for denne d\xe6mon, for hans styrke synes uden m\xe5l...\n \nAt l\xe6se denne rulle og dermed sige hans navn n\xe6r en arkan bindingscirkel vil med sikkerhed hidkalde ham dertil...\\\"\n \n \nHmm, n\xe6r en bindingscirkel... |" },
	{ 340, "\\\"Belials l\xf8jtnant kendes som Grimspike...\n \nVogt dig for denne d\xe6mon, for hans styrke synes uden m\xe5l...\n \nAt l\xe6se denne rulle og dermed sige hans navn n\xe6r en arkan bindingscirkel vil med sikkerhed hidkalde ham dertil...\\\"\n \n \nHmm, n\xe6r en bindingscirkel... |" },
	{ 341, "\\\"Belials l\xf8jtnant kendes som Grimspike...\n \nVogt dig for denne d\xe6mon, for hans styrke synes uden m\xe5l...\n \nAt l\xe6se denne rulle og dermed sige hans navn n\xe6r en arkan bindingscirkel vil med sikkerhed hidkalde ham dertil...\\\"\n \n \nHmm, n\xe6r en bindingscirkel... |" },
	{ 342, "\\\"V\xe6snet af Flamme, af Horazon\\\".|" },
	{ 343, "\\\"V\xe6snet af Flamme, af Horazon\\\".\n \n \nDet burde v\xe6re interessant l\xe6sning.|" },
	{ 344, "\\\"V\xe6snet af Flamme, af Horazon\\\".\n \n \nDet burde v\xe6re interessant l\xe6sning.|" },
	{ 345, "\\\"V\xe6snet af Flamme, af Horazon\\\".\n \n \nDet burde v\xe6re interessant l\xe6sning.|" },
	{ 346, "\\\"Ved da at binde \xe5nden til den tildannede sten gives den liv.\\\" \n \n \nDet lyder som en slags formular.|" },
	{ 347, "\\\"Ved da at binde \xe5nden til den tildannede sten gives den liv.\\\" \n \n \nDet lyder som en slags formular.|" },
	{ 348, "\\\"Ved da at binde \xe5nden til den tildannede sten gives den liv.\\\" \n \n \nDet lyder som en slags formular.|" },
	{ 349, "\\\"Ved da at binde \xe5nden til den tildannede sten gives den liv.\\\" \n \n \nDet lyder som en slags formular.|" },
	{ 350, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 351, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 352, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 353, "Morta vespa gaiya inumino evegin zhatan lua gratan|" },
	{ 354, "\\\"Det lader til, at jeg har bragt noget til dette plan, som selv jeg ikke kan styre. V\xe6snet, der faldt i min astrale f\xe6lde, er en s\xe6rdeles d\xf8""dbringende d\xe6mon. Jeg har kunnet binde det p\xe5 bunden af Hullet, men det dr\xe6""ber alt, hvad jeg har sendt derned i fors\xf8g p\xe5 at besejre det. Sk\xf8nt det ikke kan undslippe, sp\xe6rrer det tunnellerne til mit beskyttede Fristed. Jeg fristes til at bruge kontakten og \xe5""bne tunnellerne for at se, om det bare g\xe5r sin vej, men jeg frygter, det er klogere end de fleste af de mindre d\xe6moner, jeg har fanget f\xf8r. Kunne jeg blot lokke det et andet sted hen...\\\"|" },
	{ 355, "\\\"Det lader til, at jeg har bragt noget til dette plan, som selv jeg ikke kan styre. V\xe6snet, der faldt i min astrale f\xe6lde, er en s\xe6rdeles d\xf8""dbringende d\xe6mon. Jeg har kunnet binde det p\xe5 bunden af Hullet, men det dr\xe6""ber alt, hvad jeg har sendt derned i fors\xf8g p\xe5 at besejre det. Sk\xf8nt det ikke kan undslippe, sp\xe6rrer det tunnellerne til mit beskyttede Fristed. Jeg fristes til at bruge kontakten og \xe5""bne tunnellerne for at se, om det bare g\xe5r sin vej, men jeg frygter, det er klogere end de fleste af de mindre d\xe6moner, jeg har fanget f\xf8r. Kunne jeg blot lokke det et andet sted hen...\\\"|" },
	{ 356, "\\\"Det lader til, at jeg har bragt noget til dette plan, som selv jeg ikke kan styre. V\xe6snet, der faldt i min astrale f\xe6lde, er en s\xe6rdeles d\xf8""dbringende d\xe6mon. Jeg har kunnet binde det p\xe5 bunden af Hullet, men det dr\xe6""ber alt, hvad jeg har sendt derned i fors\xf8g p\xe5 at besejre det. Sk\xf8nt det ikke kan undslippe, sp\xe6rrer det tunnellerne til mit beskyttede Fristed. Jeg fristes til at bruge kontakten og \xe5""bne tunnellerne for at se, om det bare g\xe5r sin vej, men jeg frygter, det er klogere end de fleste af de mindre d\xe6moner, jeg har fanget f\xf8r. Kunne jeg blot lokke det et andet sted hen...\\\"|" },
	{ 357, "\\\"Det lader til, at jeg har bragt noget til dette plan, som selv jeg ikke kan styre. V\xe6snet, der faldt i min astrale f\xe6lde, er en s\xe6rdeles d\xf8""dbringende d\xe6mon. Jeg har kunnet binde det p\xe5 bunden af Hullet, men det dr\xe6""ber alt, hvad jeg har sendt derned i fors\xf8g p\xe5 at besejre det. Sk\xf8nt det ikke kan undslippe, sp\xe6rrer det tunnellerne til mit beskyttede Fristed. Jeg fristes til at bruge kontakten og \xe5""bne tunnellerne for at se, om det bare g\xe5r sin vej, men jeg frygter, det er klogere end de fleste af de mindre d\xe6moner, jeg har fanget f\xf8r. Kunne jeg blot lokke det et andet sted hen...\\\"|" },
	{ 358, "Lad denne foliant st\xe5 som din advarsel. Dette er et forbudt sted. Vend tilbage, hvorfra du kom, og dit liv skal spares. Horazon, mester i de discipliner der hidkalder og binder v\xe6sner til dette plan, lover d\xf8""den til dem, der g\xe5r forbi de fem s\xf8jler. Du er advaret.|" },
	{ 359, "Lad denne foliant st\xe5 som din advarsel. Dette er et forbudt sted. Vend tilbage, hvorfra du kom, og dit liv skal spares. Horazon, mester i de discipliner der hidkalder og binder v\xe6sner til dette plan, lover d\xf8""den til dem, der g\xe5r forbi de fem s\xf8jler. Du er advaret.|" },
	{ 360, "Lad denne foliant st\xe5 som din advarsel. Dette er et forbudt sted. Vend tilbage, hvorfra du kom, og dit liv skal spares. Horazon, mester i de discipliner der hidkalder og binder v\xe6sner til dette plan, lover d\xf8""den til dem, der g\xe5r forbi de fem s\xf8jler. Du er advaret.|" },
	{ 361, "Lad denne foliant st\xe5 som din advarsel. Dette er et forbudt sted. Vend tilbage, hvorfra du kom, og dit liv skal spares. Horazon, mester i de discipliner der hidkalder og binder v\xe6sner til dette plan, lover d\xf8""den til dem, der g\xe5r forbi de fem s\xf8jler. Du er advaret.|" },
	{ 362, "Det lyder som en god id\xe9. Du m\xe5 hellere komme i gang med det saaamme.|" },
	{ 363, "Dette ligger langt ud over alt, hvad jeg nogensinde har l\xe6rt. Jeg kan kun komme p\xe5 \xe9n i hele Tristram, der kunne hj\xe6lpe dig. Cain, naturligvis.|" },
	{ 364, "Om forladelse, men jeg har noget at fort\xe6lle, som du m\xe5ske finder interessant. Det var det s\xe6lsomste. Mens Farnham drak p\xe5 kroen, vr\xf8vlede han om noget, der hed Azurewrath. Han sagde ogs\xe5 noget om en falden engel. Han var sv\xe6r at forst\xe5, for han var meget fuld og forvirret, men jeg mener at huske noget om en n\xf8gle i en t\xf8nde. Han blev ogs\xe5 ved med at d\xe6kke sit ansigt og gentage ordet 'Izual' igen og igen. |" },
	{ 365, "Ved du hvad, nu hvor jeg t\xe6nker over det, var det m\xe5ske ikke en n\xf8gle i en t\xf8nde, men en t\xf8nde, der var n\xf8glen. Giver det mere mening? |" },
	{ 366, "Azurewrath og Izual. Jeg ved ikke, hvorfor jeg ikke huskede den historie f\xf8r. Jeg har h\xf8rt den tit nok fra min bedstemor og fort\xe6lleren Cain. N\xe5, jeg h\xe5""ber, mine oplysninger trods alt var mere til hj\xe6lp end til hinder. M\xe5 lyset lede dig, min ven. |" },
	{ 367, "Den engang stolte Izual er fanget dybt under denne verdens overflade. Hans \xe6re frataget, hans \xe5syn forandret. Han er fanget i ud\xf8""delig pinsel, sat til at skjule netop det, der kunne befri ham. |" },
	{ 368, "Farnham er begyndt at drikke t\xe6t siden sine oplevelser i labyrinten. Men i denne fordrukne mands vr\xf8vl hviler et sagn dybt m\xe6ttet af myte og mysterium. \n \nS\xe6t dig et \xf8jeblik, min ven, og lad mig fort\xe6lle om Izual og Azurewrath. \n \nSagaen om Izual foreg\xe5r under de tabte slag i Helvede. Izual var en engel, der fik betroet en hellig runeklinge, Azurewrath. \n \nUnder et dristigt angreb p\xe5 Helvedessmedjen blev Izual overfaldet af hundreder af sv\xe6rtede d\xe6moner og d\xf8""deligt s\xe5ret. \n \nUdyrene kastede den d\xf8""ende engel i et m\xf8rkt hul, hvor kaoskr\xe6""fterne forvandlede ham, mens han druknede i en malstr\xf8m af br\xe6ndende blod. \n \nOndskab besatte Izual. \n \nFjerene p\xe5 hans vinger br\xe6ndte bort og blottede l\xe6""deragtig hud, og horn br\xf8""d gennem k\xf8""det p\xe5 hans hoved. \n \nDa han endelig rejste sig af det sorte hul, var Izual ikke l\xe6ngere en engel. \n \nForvandlet til et ondskabens v\xe6sen fik han atter betroet Azurewrath, s\xe5 klingen aldrig mere skulle bruges mod Helvedes beboere. |" },
	{ 369, "Klingen Azurewrath, det er et sagn! Den blev st\xf8""bt af englesmeden Cinadide og h\xe6rdet i dommens flammer! Den, der svinger dette v\xe5""ben, vil se Helvedes legioner for sine f\xf8""dder! Fandt du den klinge, ville jeg for alvor begynde at tro, at du kunne ende det mareridt, der er overg\xe5""et vores by. |" },
	{ 370, "Farnham er ofte forvirret, men han n\xe6vner et m\xe6gtigt navn, n\xe5r ordet 'Izual' g\xe5r over hans l\xe6""ber. \n \nCain ville kunne fort\xe6lle dig sagnet om denne kriger langt mere indg\xe5""ende. |" },
	{ 371, "Fandt du s\xe5 meget som et spor af Izual eller klingen Azurewrath, ville selv jeg v\xe6re imponeret. Den er absolut enest\xe5""ende. |" },
	{ 372, "Der findes en gammel historie om en engel ved navn Izual, men mere end det husker jeg ikke. |" },
	{ 373, "Har du h\xf8rt den, Cain fort\xe6ller? \n \nDen elsker jeg. |" },
	{ 374, "Hvor er det dumme kort? Det skulle ligge mellem en sten og et tr\xe6 f\xf8r broen. Burde v\xe6re lige her... \n \n\xc5h, goddag. S\xe5, \xf8h, ikke lige, at du stod der. |" },
	{ 375, "Der var en tid, hvor denne by var et hyppigt stop for rejsende fra n\xe6r og fjern. Meget har \xe6ndret sig siden. Men skjulte huler og begravede skatte er almindelige fantasier hos ethvert barn. Wirt hengiver sig sj\xe6ldent til barnlige lege. S\xe5 det kan v\xe6re hans fantasi.|" },
	{ 376, "Sten? Tr\xe6? Bro? \n \nJeg aner ikke, hvad du taler om. |" },
	{ 377, "Hold fast i din f\xe6rd. At finde en tabt skat er ikke let. At finde en skjult endnu mindre. Jeg efterlader dig med dette: lad ikke tidens sand forvirre din s\xf8gen.|" },
	{ 378, "En hvad?! Det er t\xe5""belighed. Der ligger ingen skat begravet her i Tristram. Lad mig se det! Ha, se, tegningerne er un\xf8jagtige. De passer slet ikke p\xe5 vores by. Jeg ville holde tankerne p\xe5, hvad der ligger under katedralen, og ikke hvad der ligger under vores muldjord.|" },
	{ 379, "Jeg t\xf8r v\xe6""dde p\xe5, at Wirt s\xe5 dig komme og spillede komedie, bare s\xe5 han kunne grine ad dig senere, n\xe5r du rendte rundt i byen med n\xe6sen i jorden. Jeg ville ignorere det.|" },
	{ 380, "Hov, lad mig se det. \n \n*Pudser n\xe6se* \n \nTak! |" },
	{ 381, "Hej, du der! Kom her, h\xf8r efter! Kender du \xf8""en, hvor engle v\xe5ger? V\xe6lg de rigtige sten, men du m\xe5 hellere sk\xe6rme dine \xf8jne, sk\xe6rme alt! Jeg ved det, for jeg har v\xe6ret der, og... mmm, \xf8l. |" },
	{ 382, "Ved du, somme tider undrer jeg mig over, hvor megen lid man kan f\xe6ste til det, Farnham siger. Han bruger s\xe5 megen tid p\xe5 at genopleve sine minder fra labyrinten og p\xe5 bare at v\xe6re fuld, at han ikke altid giver megen mening. Men du kan jo sp\xf8rge dig for. |" },
	{ 383, "Det er en drukkenbolts ord. \n \nJeg ser ikke, hvordan de skulle v\xe6re sande. |" },
	{ 384, "For \xe9n gangs skyld b\xf8r du lytte til Farnham. Jeg har h\xf8rt om dette sted, og jeg kender et par troldm\xe6nd, der har fors\xf8gt at skabe en portal dertil. |" },
	{ 385, "Dette sagnomspundne sted er virkeligt. Og store bel\xf8nninger venter dig, hvis du finder det. Mere kan jeg ikke sige. |" },
	{ 386, "For \xe9n gangs skyld kan jeg st\xe5 inde for Farnhams utrolige p\xe5stand. \n \n \nDer er mange omtaler i de b\xf8ger, jeg har l\xe6st, af et sted med stor l\xe6gedom, hvor lysets krigere tog hen for at hele de s\xe5r, de fik i Syndekrigen. \n \n \nKunne du finde dette sted, ville det uden tvivl v\xe6re til gavn for os alle. |" },
	{ 387, "Hmm, en \xf8, hvor engle v\xe5gede? Sk\xf8nt Farnhams hukommelse ofte er t\xe5get nu om dage, lyder det bekendt. M\xe5ske kan Syndekrigens \xe6ldgamle kr\xf8niker hj\xe6lpe os. \n \nAh, ja, her er noget. I en for l\xe6ngst glemt tid l\xe5 et bl\xe5t hav p\xe5 kanten af en flammende underverden. Det var en oase for dem, der stod vagt over helvedes porte. Engle og lysets krigere kunne bruge stedet til at hele sig selv og samle kr\xe6""fter. Det var ogs\xe5 et samlingssted, hvor de kunne \xf8ve sig og berede sig p\xe5 Syndekrigen. Sagn taler om en treenighed af sten, der skjuler vejen til denne \xf8 i det soll\xf8se hav. |" },
	{ 388, "Farnham taler om et sted, der findes, i det mindste i sagnene. Krigere tog til et sted p\xe5 kanten af helvede for at ruste sig til kamp mod m\xf8rkets h\xe6re. Er historierne sande, kan der ligge utalte skatte p\xe5 denne \xf8 i det soll\xf8se hav. |" },
	{ 389, "Jeg har haft en h\xf8jst foruroligende oplevelse, jeg m\xe5 dele med dig, min ven. \nTidligere i dag blev jeg kaldt ud for at hj\xe6lpe en af de m\xe6nd, der undslap labyrinten. Han var fra forstanden, voldsom, og han blev ved at sl\xe5 ud efter alle, der pr\xf8vede at berolige ham. Jeg havde mistanke om, at han var besat af en slags d\xe6monisk v\xe6sen, og gav mig til at drive det onde ud af ham.  \n \nEfter mange timer lykkedes det mig at uddrive en d\xe6mon, der kaldte sig \\\"Fleshdoom\\\", men udyret flygtede ned i labyrinten. \nDu synes m\xe5ske, jeg er gal, men efter at have talt med manden og k\xe6mpet med Fleshdoom tror jeg, at labyrinten p\xe5 en eller anden vis er blevet en port til underverdenen. N\xe5r du stiger dybere ned, kan du finde dig selv p\xe5 selve Helvedes d\xf8rtrin.\nEndelig: den besatte mand havde minder om en \xe6ldgammel d\xe6monklinge ved navn \\\"Shadowfang\\\". Finder du d\xe6monen Fleshdoom, s\xe5 vogt dig for det gr\xe6sselige sv\xe6rd. Og jeg frygter, at farerne dernede vokser sig endnu st\xf8rre.\nDu M\xc5 finde Fleshdoom og dr\xe6""be ham. Bring mig sv\xe6rdet, s\xe5 kan jeg tilintetg\xf8re det, men SVING DET IKKE! For dets magt kan ford\xe6rve fuldst\xe6ndigt! |" },
	{ 390, "Alt, jeg kan g\xf8re nu, er at bede for os alle... |" },
	{ 391, "Fleshdooms endeligt er et stort gode for verden, men Shadowfang best\xe5r! Det m\xe5 findes og tilintetg\xf8res! Fors\xf8g ikke at bruge d\xe6monklingen, fork\xe6mper. Den vil ford\xe6rve og forrykke enhver d\xf8""delig, der svinger den. Kun jeg kan ende dens m\xf8rke ondskab. |" },
	{ 392, "Hvorfor t\xf8ver du? Tiden er knap! Prinsen og folket i dette kongerige regner med dig. |" },
	{ 393, "Lyset v\xe6re lovet! Du fandt den forbandede d\xe6monklinge. Kun dens tilintetg\xf8relse kan sikre os alle. Vent, hvilket forr\xe6""deri er dette? Av! Det br\xe6nder! Helvedesild... fort\xe6rer mig! Du m\xe5 bringe den til Helvedessmedjen og kaste den i, f\xf8r... Neeeej! |" },
	{ 394, "Jeg h\xf8rte, at pr\xe6sten Tremain ville udf\xf8re en eksorcisme, men jeg gik ikke derhen. Jeg ser ikke, hvorfor vi alle skal leve hvert \xf8jeblik som fanger af det, der lurer under vores by. Jeg ved, at mange er d\xf8""de for disse monstres h\xe6nder, men vi m\xe5 pr\xf8ve at komme videre. Jeg ved, at du er kommet for at befri Tristram fra m\xf8rkets kl\xf8""er, og jeg h\xe5""ber, at vi en dag kan leve i fred igen. |" },
	{ 395, "Ah, du taler om et \xe6ldgammelt og ondt v\xe5""ben. Tr\xe6""d varsomt her, for sagnene om Shadowfang er sorte som en m\xe5nel\xf8s vinternat. Smedet i Helvedessmedjen kan Shadowfang fl\xe6nse selve sj\xe6len ud af den, det rammer. Jeg misunder dig ikke, hvis du har i sinde at besejre den, der svinger det. M\xe5 lyset beskytte dig, tapre helt. |" },
	{ 396, "Du vil jage en d\xe6mon, var det, hvad du sagde? Jeg ved, jeg ikke h\xf8rte det, for ingen jager d\xe6moner! N\xe6h! Ingen! |" },
	{ 397, "Jeg blev bedt om at hj\xe6lpe til ved eksorcismen. Mine evner kunne lindre den stakkels mands lidelser, mens Tremain drev d\xe6monen ud af hans krop. Mens jeg behandlede ham for en us\xe6""dvanlig h\xf8j feber, talte han om et sted med svidende hede. Den pinte mand r\xe5""bte om Helvede og om at falde i et flammehul. Jeg kunne ikke f\xe5 mening ud af det, og heldigvis kom han sig snart. |" },
	{ 398, "Jeg ved ikke, hvem denne Fleshdoom er, men jeg har h\xf8rt rygter om en sort klinge, der kl\xf8ver sj\xe6len fra kroppen. Selv jeg ville ikke pr\xf8ve at s\xe6lge den tingest, uanset fortjenesten. Finder du den, b\xf8r du g\xf8re, som Tremain siger, og tilintetg\xf8re den hurtigst muligt. |" },
	{ 399, "Pr\xe6sten Tremain er en hellig mand af en \xe6ldgammel orden. Deres omgang med de onde kr\xe6""fter er h\xf8jt respekteret og vel dokumenteret. Ogs\xe5 jeg har h\xf8rt sagn om en forbandet d\xe6monklinge kaldet Shadowfang. Den siges at fort\xe6re sine ofres pinte sj\xe6le. Disse sj\xe6le er fanget i dens sorte klinge og forst\xe6rker dens vanhellige kraft. Jeg har ogs\xe5 l\xe6st om en stor Helvedessmedje, hvor selv det m\xe6gtigste v\xe5""ben kunne skabes eller tilintetg\xf8res. Tr\xe6""d varsomt i omgang med Shadowfang og dens herre, s\xe5 du ikke selv drages ind i sv\xe6rdet. |" },
	{ 400, "Jeg s\xe5 eksorcismen. Det var utroligt, hvordan Tremain drev den onde \xe5nd ud af mandens forpinte krop. Jeg beder til, at noget s\xe5 gr\xe6sseligt aldrig sker for nogen her igen. |" },
	{ 401, "Du m\xe5 v\xe6re evigt \xe5rv\xe5gen, for Fleshdoom er en fjende, b\xe5""de grusom og hurtig. Hans sorte klinge er gjort af ondskabens essens. Kan du tilintetg\xf8re dem begge, vil det g\xf8re meget for at sv\xe6kke hans m\xf8rke herre. |" },
	{ 402, "Sk\xf8nt jeg forst\xe5r, at dit form\xe5l kan v\xe6re et h\xf8jere kald, ville noget velfortjent guld sikkert v\xe6re velkomment. Nogle byboere fra en n\xe6rliggende landsby har udlovet en bel\xf8nning for at tilintetg\xf8re et v\xe6sen, der har h\xe6rget deres hjem og ejendom. De kr\xe6ver sikkert bevis for, at v\xe6snet er dr\xe6""bt, og jeg kan kun komme p\xe5 \xe9n m\xe5""de at g\xf8re det. |" },
	{ 403, "Du kan sige, hvad du vil, men uden bevis kan jeg ikke give dig bel\xf8nningen. |" },
	{ 404, "Adr, modbydeligt! Men bestemt bevis nok for enhver. Her er din bel\xf8nning, som lovet. |" },
	{ 408, "Gode mester, et \xf8jeblik af din tid. Der blev brudt ind i min kro i nat. Ingen kom noget til, men mange ting blev stj\xe5let, deriblandt en kiste, der tilh\xf8rte en g\xe5""defuld vandringsmand, som engang boede her. Jeg fandt liget af en tyv n\xe6r katedralen, med tydelige s\xe5r fra et af v\xe6snerne dernede p\xe5 hans s\xf8nderbrudte krop. Noget af tyvekosterne l\xe5 n\xe6r liget, men kisten, og n\xf8glen til at \xe5""bne den, var intetsteds at se. Skulle du finde de n\xf8gler p\xe5 dine f\xe6rd, s\xe5 husk dem. |" },
	{ 409, "Husk, gode mester: kisten er l\xe5st og ubrugelig uden n\xf8glen. Finder du kisten og f\xe5r n\xf8glen, b\xf8r du se, hvad der er indeni. Jeg... venter ikke ejeren tilbage her igen. |" },
	{ 410, "Jeg ser, at du har fundet n\xf8glen. Nu skal du blot finde den kiste, den h\xf8rer til. |" },
	{ 411, "Dine tapre beretninger om kampe mod d\xe6moner har mindet mig om noget, gode mester. En rejsende drog her igennem for nogen tid siden. Han var s\xe6rdeles stolt af et h\xf8jst enest\xe5""ende v\xe5""ben, han bar, og da han blev godt fuld, pralede han af dets magt. Jeg s\xe5 ham aldrig igen, og jeg formoder, han vovede sig for t\xe6t p\xe5 katedralen. |" },
	{ 412, "Har du set den rejsende, jeg fortalte dig om? Ham med det fortryllede v\xe5""ben? Tja, han har vel forladt vores landsby som s\xe5 mange andre, eller ogs\xe5 er han d\xf8""d. |" },
	{ 413, "Ja, det er bestemt det v\xe5""ben, han bar. Ved du, jeg har t\xe6nkt over noget andet, den rejsende sagde. Han antydede, at v\xe5""bnets sande kr\xe6""fter kun ville slippes l\xf8s, n\xe5r det smagte blodet af en ganske bestemt slags v\xe6sen. |" },
	{ 414, "Var den rejsendes historier sande? \xc5h, jeg ser, du ikke ved det endnu. Jeg husker tydeligt, at han sagde, at ved at dr\xe6""be et bestemt monster ville det v\xe5""ben, du fandt, blive noget ganske s\xe6rligt. |" },
	{ 415, "Min ven, jeg m\xe5 tale med dig. P\xe5 vej hen for at hj\xe6lpe en syg landsbyboer st\xf8""dte jeg p\xe5 en d\xe6mon i byen. Jeg flygtede fra huset... og lod ved et uheld d\xf8ren st\xe5 \xe5""ben i farten. Jeg beder til, at det nedrige v\xe6sen stadig er derinde. Hj\xe6lp os, f\xf8r det kommer efter os alle!| " },
	{ 416, "Disse v\xe6sner m\xe5 forvises fra vores by. Til min skam lod jeg d\xf8ren st\xe5 \xe5""ben, men s\xe5 er huset s\xe5 meget desto lettere at finde. |" },
	{ 417, "Endnu en gang st\xe5r byen i g\xe6ld til dig. Kun din styrke og viljekraft kan f\xf8re os ud af denne onde tid. |" },
	{ 418, "Min bedstemor dr\xf8mte om dig i nat! Hun sagde, at du i hendes dr\xf8m brugte dine bare h\xe6nder til at besejre et af de gr\xe6sselige monstre, der lurer under kirken. Da det d\xf8""de, eksploderede det i pragtfulde skatte. Sk\xf8nt hun blev lidt skr\xe6mt af dr\xf8mmen, kunne hun beskrive b\xe6stet ganske tydeligt for mig...|" },
	{ 419, "Min bedstemor havde n\xf8jagtig den samme dr\xf8m igen! Hun sagde, du var meget tapper og virkede s\xe6rdeles tilfreds med din gevinst. |" },
	{ 420, "Hold \xf8jnene \xe5""bne efter en figur af jern. Jeg har fundet gamle optegnelser om en bestemt slags figur og de metalsmedehemmeligheder, den rummer. Ser du det, jeg leder efter, s\xe5 tag det og bring mig det straks. |" },
	{ 421, "\xc5h, dette metals hemmeligheder er fantastiske! \n \n\xc5h, hvor kunne jeg f\xe5 den rette genstand til at str\xe5le af kraft... \n \nJeg kunne smede noget v\xe6rdigt til himlens krigere! |" },
	{ 422, "Din indsats er ikke forg\xe6ves. Alt er, som jeg havde h\xe5""bet. \n \nJeg stoler p\xe5, at du finder dette nyttigt i dine kampe dernede. |" },
	{ 423, "Endnu en gang beh\xf8ver jeg din st\xe6rke arm og dit hurtige hoved for at hj\xe6lpe denne bys folk. Jeg mangler visse reagenser til at bek\xe6mpe de plager, d\xe6monerne alene ved deres tilstedev\xe6relse har sluppet l\xf8s over landet. Kan du samle disse f\xe5 ting, vil det redde mange liv.| " },
	{ 424, "Sygdommene breder sig hurtigt, og mange d\xf8r. Hj\xe6lp mig med at finde reagenserne, s\xe5 jeg kan lave en modgift. |" },
	{ 425, "Tusind tak! Du bringer h\xe5""b og lys i disse m\xf8rke og urolige tider. \n \nJeg \xf8nsker, at du skal have dette, i h\xe5""bet om at det vil hj\xe6lpe dig i din kamp mod m\xf8rket. |" },
	{ 426, "Jeg er heldig! En karavane er standset lige uden for landsbyen og bringer forsyninger til landene mod \xf8st. Visse varer indbringer en s\xe6rlig pris, hvis du kan skaffe mig dem. |" },
	{ 427, "Vi kan begge tjene godt, hvis du kan levere de rette varer til mig. Hvad siger du? |" },
	{ 428, "Ah, du kommer lige i rette tid. Karavanen tager af sted i aften. Her er din andel, min ven. |" },
	{ 429, "H\xf8r, jeg ved godt, mine priser er h\xf8je, men... en af mine kontakter havde et... uheld.\n \n \nOg jeg beh\xf8ver hj\xe6lp til at genopfylde mit mere almindelige varelager. \n \n \nJeg bytter dig en kvalitetsvare, hvis du blot ordner denne lille liste for mig. |" },
	{ 430, "H\xf8r, jeg skal nok g\xf8re det din tid v\xe6rd, hvis du skaffer mig det, jeg bad om. Desuden ved du godt, at du gerne vil se, hvad jeg giver til geng\xe6ld... |" },
	{ 431, "Tak. Det her b\xf8r r\xe6kke, til jeg finder en ny bydreng. Skam, du har s\xe5 travlt. N\xe5 ja, her er din del af handlen. |" },
	{ 432, "Hey, du! Ja, det er dig, jeg taler til! Jeg har... erhvervet denne s\xe6lsomme bog. Jeg ved, den m\xe5 kunne noget stort, men man skal bruge et krystalokular for at l\xe6se den, s\xe5 den er ubrugelig for mig. Men jeg er villig til at bytte dig denne sj\xe6ldne og mystiske foliant for blot et par ting. |" },
	{ 433, "H\xf8r, denne helt s\xe6rlige bog kan blive din for n\xe6sten ingenting. Fort\xe6l ikke nogen, hvilken god handel jeg giver dig, det ville \xf8""del\xe6gge mit ry... |" },
	{ 434, "Utroligt! Du fandt faktisk alt, hvad jeg ville have. N\xe5, her er bogen, men du m\xe5 finde et krystalokular for at l\xe6se den. Held og lykke! |" },
	{ 435, "Min bedstemor fort\xe6ller mig tit historier om de s\xe6lsomme kr\xe6""fter, der bebor kirkeg\xe5rden uden for kirken, og en af dem kunne interessere dig. Hun sagde, at hvis man lagde det rette offer p\xe5 kirkeg\xe5rden, gik ind i katedralen for at bede for de d\xf8""de og s\xe5 vendte tilbage, ville offergaven v\xe6re forandret p\xe5 en s\xe6lsom m\xe5""de. Jeg ved ikke, om det blot er en gammel, syg kones snak, men alt synes muligt nu om dage.|" },
	{ 436, "Jeg ved, at min bedstemors historie lyder s\xe6lsom, men kirkeg\xe5rden er nu omgivet af mange g\xe5""der.  \n \nDet kunne vel ikke skade at l\xe6gge noget derud og se, hvad der sker?  \n \nM\xe5ske finder du noget, der kan hj\xe6lpe os alle.|" },
	{ 437, "Jeg tror, jeg har fundet en m\xe5""de at forbedre visse v\xe5""ben betydeligt. Kan du bringe mig, hvad jeg beh\xf8ver, vil jeg gerne afpr\xf8ve min id\xe9, og virker den, er den din.|" },
	{ 438, "Ah, jeg tror stadig, jeg kan forbedre det rette v\xe5""ben.|" },
	{ 439, "Lad mig lige g\xf8re s\xe5""dan... og s\xe5""dan... og s\xe5""dan. Ha! Det virker. Tag den tilbage og pr\xf8v den.|" },
	{ 440, "Jeg ved, at jeg beder dig om meget, men jeg m\xe5 nu bede dig finde en dam med rent vand.\n \nTag disse beholdere. Fyld dem, og bring dem tilbage, s\xe5 snart du kan. \n \nMed det rene vand kan jeg skabe en eliksir af vidunderlig kraft til gavn for os alle.|" },
	{ 441, "Har du, hvad jeg beh\xf8ver? Det rene vand vil lade mig skabe en meget kraftfuld eliksir. Fyld beholderne, jeg gav dig, og vend tilbage med dem.|" },
	{ 442, "Udm\xe6rket, min ven! Udm\xe6rket! \n \nGiv mig blot et \xf8jeblik til at blande ingredienserne... perfekt! \n \nHer er noget af eliksiren, som lovet.|" },
	{ 443, "Dine tapre beretninger om kampe mod d\xe6moner har mindet mig om noget, gode mester.\n \nEn rejsende drog her igennem for nogen tid siden. \n \nHan var s\xe6rdeles stolt af et h\xf8jst enest\xe5""ende v\xe5""ben, han bar, og da han blev godt fuld, pralede han af dets magt. \n \nJeg s\xe5 ham aldrig igen, og jeg formoder, han vovede sig for t\xe6t p\xe5 katedralen.|" },
	{ 444, "Har du set den rejsende, jeg fortalte dig om? Ham med det fortryllede v\xe5""ben? Tja, han har vel forladt vores landsby som s\xe5 mange andre, eller ogs\xe5 er han d\xf8""d.|" },
	{ 445, "Ja, det er bestemt det v\xe5""ben, han bar. \n \nVed du, jeg har t\xe6nkt over noget andet, den rejsende sagde. Han antydede, at v\xe5""bnets sande kr\xe6""fter kun ville slippes l\xf8s, n\xe5r det smagte blodet af en ganske bestemt slags v\xe6sen.|" },
	{ 446, "Det lader til, at rullerne, der findes under kirken, har mange anvendelser. \n \nJeg burde kunne nedskrive en magibog, hvis jeg havde nok af de rette ruller at studere.|" },
	{ 447, "Husk, med nok ruller kan jeg skabe en magibog til dig.|" },
	{ 448, "Ja, jeg kan se, at n\xe5r jeg kombinerer disse ruller netop s\xe5""dan... \n \nJeg vil l\xe6re dig, hvad jeg har l\xe6rt, s\xe5 du ogs\xe5 kan kende flere af denne magis hemmeligheder.|" },
	{ 449, "Du er udvalgt til at blive en af mine tjenere.\n \nTjen mig vel, og jeg giver dig magt og rigdom hinsides dine vildeste dr\xf8mme.\n \nSvigt mig, og din l\xf8n bliver endel\xf8s lidelse.\n \nDin f\xf8rste opgave er at hindre, at Tristrams vandforsyning renses. Tag derhen og skaf de irriterende helte af vejen.|" },
	{ 450, "Jeg har endnu en mission til dig.\n \nAt holde vandforsyningen forurenet efterlod heltene tomh\xe6ndede, og de har indledt et overraskelsesangreb p\xe5 De Stille Kilder i jagten p\xe5 rent vand.\n \nDu tager straks til De Stille Kilder og s\xf8rger for, at de finder d\xf8""den i stedet for vand.|" },
	{ 451, "Vandet er bag os. Det, der kommer nu, er v\xe6rre og farligere.\n \nEn af deres skrivere har skrevet. Hver br\xf8nd, hvert lig, hver hvisken - han syr dem sammen til \xe9n side, og den side ender med mit navn og vejen til min d\xf8r.\n \nTag til Det Nedre Skriptorium og skaf den skriver af vejen. Portalen er \xe5""ben. V\xe6r hurtig.|" },
	{ 452, "Godt arbejde med skriveren. Det k\xf8""ber os tid.\n \nI mellemtiden er ord om en forr\xe6""der n\xe5""et mig.\n \nDer findes en plage ved navn Az'dog. Et navn lige s\xe5 dumt som dets b\xe6rer. En af underd\xe6monerne. Falden. Han og hans f\xe6ller har b\xe5ret hviskerier til mennesker.\n \nDette t\xe5les ikke. Jeg vil have den vederstyggelighed lige s\xe5 d\xf8""d som en helt frataget sin rustning i et hul fuldt af udsultede lig\xe6""dere.\n \nPortalen er \xe5""ben. G\xe5 og giv v\xe6snet dets 'bel\xf8nning'.|" },
	{ 453, "Forr\xe6""deren er d\xf8""d, men skaden er sket. Han havde allerede talt, og de handler allerede p\xe5 det. Jeg har undervurderet disse heltes st\xe6""dighed.\n \nLige meget. Det bliver kun en mindre forsinkelse.\n \nFire af deres kaptajner har kaldt til r\xe5""d p\xe5 et sted, de tror er hemmeligt, og planl\xe6gger deres n\xe6ste tr\xe6k.\n \nDu afl\xe6gger dem et bes\xf8g. Men v\xe6r advaret: dette er ikke de stakler, du har slagtet hidtil. De er st\xe6rkere, bedre pansrede og kamperfarne. Bered dig vel denne gang.|" },
	{ 454, "De graver igen. De s\xf8ger en grav, en d\xf8""d ridder, rustningen han r\xe5""dnede i - de s\xf8ger den hellige rustning kaldet Arkaines Tapperhed. T\xe5""berne tror, det er et \xe6ldgammelt relikvie, der vil vende Syndekrigens gang. Det er blot st\xe5l p\xe5 et lig. Intet s\xe6rligt.\n \nMen tr\xe6k det frem i dagslyset, og enhver bonde med en h\xf8tyv husker, hvordan man h\xe5""ber.\n \nG\xe5 og dr\xe6""b graverne. Dr\xe6""b den, der kom for at b\xe6re den. Efterlad dem i d\xf8r\xe5""bningen, hvor den n\xe6ste ekspedition finder dem. Tag rustningen bagefter, hvis det morer dig. Hvis ikke, s\xe5 smid den v\xe6k. Jeg er ligeglad.|" },
	{ 455, "Du kommer lige i rette tid.\n \nI g\xe5r, under en patrulje, st\xf8""dte en gruppe Overherrer p\xe5 en stor styrke af bev\xe6""bnede helte i omr\xe5""det kendt som Kloakkerne. De k\xe6mpede tappert mod overmagten, men blev udslettet.\n \nJeg sendte en gruppe p\xe5 50 kampvante Huld\xe6moner for at ordne sagen, og de er nu i \xe5""ben kamp med heltene. Sk\xf8nt de med held har presset heltene op i Kloakkernes nordlige del, har deres tab v\xe6ret enorme. Dette slag er tabt.\n \nDin mission er at tage derhen og fuldf\xf8re det arbejde, de begyndte. Udryd alle tilbagev\xe6rende heltestyrker, men vent h\xe5rd modstand. Det er en riddertrop tr\xe6ngt op i en krog uden retr\xe6temulighed, og de vil med sikkerhed k\xe6mpe til d\xf8""den. Du s\xf8rger for, at de g\xf8r netop det.|" },
	{ 456, "Du har ordnet disse riddere uden n\xe5""de og uden t\xf8ven. Nu er det tid til at pr\xf8ve dine evner.\n \nJeg har meldinger om en stor forsamling af helte i De \xc6ldgamle Krypter. Det er t\xe6t nok p\xe5 mit tilholdssted. Jeg t\xe5ler ikke deres tilstedev\xe6relse i dette omr\xe5""de - og det er en belejlig chance for at lamme deres fremtidige virke her.\n \nDit m\xe5l er at udrydde s\xe5 mange helte som muligt. Udvisk hvert spor af dem fra dette sted. Det tilh\xf8rer d\xe6moner, ikke mennesker.|" },
	{ 457, "Den M\xf8rke Rede g\xe5r dybere, end yngelen beh\xf8ver.\n \nDens laveste tunneller \xe5""bner sig mod Krypten. De helte, der n\xe5""ede den, ved det nu.\n \nDe er deroppe nu og l\xe6rer nedstigningen godt nok til at l\xe6re den fra sig.\n \nDu g\xe5r ind i en kamp ulig nogen, du hidtil har oplevet. De kom gennem yngelen og overlevede, og deres tro, hvor vildledt den end er, giver dem styrke.\n \nDr\xe6""b dem alle. Efterlad ingen til at tegne kortet.|" },
	{ 458, "De er vendt tilbage til vandforsyningen. Igen. Og de har sendt deres bedste.\n \nG\xe5 tilbage og tag den fra dem igen. Efterlad dem intet. Ikke vandet, ikke m\xe6ndene, ikke tanken om at noget af det nogensinde var v\xe6rd at fors\xf8ge. Lad dem drikke deres eget blod.\n \nDisse to vil hj\xe6lpe dig p\xe5 missionen.|" },
	{ 459, "Godt arbejde med heltene i vandforsyningen. De t\xe6nker sig om to gange, f\xf8r de angriber det sted igen.\n \nMen jeg har en anden vigtig sag at se til. Hephasto, en af Helvedes dygtigste v\xe5""bensmede, \xf8nsker det sagnomspundne artefakt kaldet Raseriets Ambolt. Han tror, at denne ambolt vil lade ham smede v\xe5""ben og rustninger af bedre kvalitet, hvilket igen giver d\xe6moner en fordel i kamp. Jeg agter at st\xf8tte hans sag.\n \nOg du bliver den, der henter ambolten til ham.\n \nOrd om, at heltene ogs\xe5 s\xf8ger den, er ligeledes n\xe5""et mig. S\xe5 du m\xe5 skaffe dem af vejen, hvis de viser sig, hvor du skal hen.\n \nOg du skal til et omr\xe5""de kendt som De Dybere Huler. Bring mig ambolten. S\xe5 skal vi vise de t\xe5""ber deroppefra, at der ikke findes d\xf8""dbringendere v\xe5""ben end dem, der er smedet i Helvede.|" },
	{ 460, "fortrinligt. ambolten skal nok g\xf8re sit.\n \nnu til andre sager.\n \njeg h\xf8rer, at heltene har en ny general, der lover at knuse det onde i labyrintens dyb. Hans trop er p\xe5 vej ned mod krypterne. du m\xe5 opsnappe dem p\xe5 stedet kendt som Pandemonium.|" },
	{ 461, "Min h\xf8jtst\xe5""ende tjener har bragt sig selv i knibe.\n \n\xc6rkebiskop Lazarus. Hans skjulested \xf8verst i Tristrams katedral angribes af elitestyrker af helte.\n \nJeg sender pigerne i forvejen for at hj\xe6lpe gode Lazarus, men jeg sender ogs\xe5 dig for at v\xe6re sikker.\n \nMissionen er ikke at lade Lazarus d\xf8.\n \nSvigter du og lader Lazarus d\xf8, f\xf8lger du hurtigt i hans fodspor.|" },
	{ 462, "Hvad laver du her? Hvordan kom du herind? Hvem har sendt dig?\n \nMesteren? Priset v\xe6re min herre!\n \nDin timing var uovertruffen. Tag dette som tegn p\xe5 min p\xe5sk\xf8nnelse.\n \nMen lad mig nu v\xe6re. Jeg m\xe5 hvile.|" },
	{ 463, "Tre hovmodige troldm\xe6nd gemmer sig i Blodborgen med deres skatte. Jeg vil have dem d\xf8""de. Og jeg vil have deres guld bragt til mig. Min d\xe6monh\xe6r g\xf8r bedre brug af det.\n \nOg du f\xe5r ogs\xe5 din andel. Du bliver ikke skuffet.|" },
	{ 464, "Helvedessmedjen er under angreb. Hephasto beh\xf8ver beskyttelse. S\xe5 g\xf8r noget beskyttende.\n \nOg et godt r\xe5""d: bered dig vel. Jeg h\xf8rer, de har sendt en hel del pansrede riddere derhen. Den slags er farligere.|" },
	{ 465, "Godt arbejde. Det skulle l\xe6re dem at angribe Helvedessmedjen.\n \nOg du, tag dette v\xe5""ben. Det er nysmedet p\xe5 Raseriets Ambolt.\n \nM\xe5 det tjene dig vel mod horden af overfladeboere.|" },
	{ 466, "Din n\xe6ste mission g\xe5r til den underjordiske labyrint kaldet Den Stinkende Grotte.\n \nJeg ved ikke, hvorfor de sendte tropper til det omr\xe5""de, og jeg vil ikke vide det. Jeg vil bare have dem alle d\xf8""de.\n \nPortalen er \xe5""ben. Begynd.|" },
	{ 467, "Min h\xe6r presser heltene tilbage mod overfladen. De er ude af Helvede nu. Frontlinjen er rykket til Hulerne.\n \nOg din n\xe6ste opgave er Minehulerne. Det er her, en elitetrop af bueskytter er set. Dit m\xe5l er at udrydde den. Jeg sender en d\xe6montrop bagefter til at samle resterne af dem op.|" },
	{ 468, "Det lader til, vi har lidt endnu et tilbageslag, og heltene stormer Helvedesporten.\n \nSk\xf8nt det, det er jeg vis p\xe5, er det sidste tilbageslag, m\xe5 du rejse til Helvedesporten og g\xf8re en ende p\xe5 den trop af menneskelig modstand.\n \nG\xf8r det hurtigt. Vi m\xe5 videre opad. Vi er ved at bryde ind i katakomberne. Slutfasen er n\xe6r.|" },
	{ 469, "Helvedesporten er under kontrol nu. Endelig.\n \nS\xe5 til din n\xe6ste mission. Mine spejdere fulgte en af de flygtende heltegrupper op i de \xf8vre grotteniveauer. De melder, at heltene bruger den s\xe6""dvanlige vej ned fra katakomberne, men at der findes en anden. Et \xe6ldgammelt omr\xe5""de. De kalder det Nekropolis. Som ventet opdagede de, hvorfor heltene ikke bruger denne vej til grotterne: den er st\xe6rkt bef\xe6ngt med ud\xf8""de. Det lidt, man ved om stedet, tyder p\xe5, at det var et hemmeligt gravsted for medlemmer af Horadrim, den hemmelighedsfulde magikerorden, der f\xe6ngslede mig og mine br\xf8""dre for l\xe6nge siden.\n \nJeg vil have deres rester tilintetgjort og gjort til st\xf8v. End ikke i d\xf8""den skal de finde frelse fra min h\xe6vn. Dette er dit hovedm\xe5l for missionen: tilintetg\xf8r alle Horadrim-medlemmer, der er steget af deres grave.\n \nDit sekund\xe6re m\xe5l er at rydde hele Nekropolis og dermed g\xf8re det til en sikker passage for min h\xe6r. Det b\xf8r give os en fordel i at n\xe5 overfladen hurtigere.|" },
	{ 470, "Tiden til at f\xf8re kampen til menneskenes omr\xe5""de er nu.\n \nMed Nekropolis som sikker passage for min h\xe6r kan vi ramme menneskenes modstand i katakomberne. Det er deres omr\xe5""de. Bygget af mennesker. Men ikke l\xe6nge. Snart tilh\xf8rer det d\xe6moner.\n \nOmr\xe5""det over Nekropolis tjener som kaserne for deres styrke. Det kendes som Galgen. Og det er her, vi sl\xe5r til n\xe6ste gang. G\xf8r dine forberedelser og tag straks af sted.\n \nTr\xe6""d af.|" },
	{ 471, "En af spejderne vendte tilbage i dag og meldte, at en stor trop ildtroldm\xe6nd er p\xe5 vej mod hulerne gennem omr\xe5""det Gravkapellet. Du tager derhen \xf8jeblikkeligt. Dit m\xe5l er at opsnappe og udrydde denne trop.\n \nDit sekund\xe6re m\xe5l er at dr\xe6""be s\xe5 mange heltestyrker i omr\xe5""det som muligt.\n \nDer er ingen tid at spilde. Af sted. Nu.|" },
	{ 472, "Soldat.\n \nHver dag bringer os n\xe6rmere det endelige opg\xf8r med overfladeboerne. Min h\xe6r har l\xe6rt nye taktikker, udvidet sit arsenal og styrket sit herred\xf8mme. Men menneskene er stadig for mange og for m\xe6gtige. I underverdenen siger vi, at dr\xe6""ber man en slange, hugger man hovedet af den. Men i denne situation m\xe5 vi f\xf8rst sv\xe6kke den. Begynd med halen og arbejd dig mod hovedet.\n \nMin h\xe6r er n\xe5""et til katedralens laveste niveauer. Den er direkte forbundet med overfladen. Dette er det sidste fremst\xf8""d. Og det er det, heltene vil forsvare med n\xe6""b og kl\xf8""er.\n \nDu rejser til omr\xe5""det Det \xd8""delagte Tempel og s\xf8rger for, at det renses for menneskelig trussel. D\xe6moner vil bruge dette hemmelige k\xe6lderniveau til ubem\xe6rket at str\xf8mme ind i katedralen.\n \nVi g\xe5r ind i min plans sidste fase. Men tro ikke, det er forbi, n\xe5r vi erobrer overfladen. Der er st\xf8rre planer, der r\xe6kker ud over det. Men dem afsl\xf8rer jeg senere.\n \nFrem for alt: fuldf\xf8r din mission, men hold \xf8jnene \xe5""bne for enhver yderligere oplysning eller svaghed, der m\xe5tte vise sig.\n \nPortalen er \xe5""ben. Begynd.|" },
	{ 473, "Mens mine styrker k\xe6mper mod helte i katedralens nedre niveauer, m\xe5 du rejse til det fangehul, hvor heltene opbevarer deres ressourcer, og infiltrere det. Tag alt af v\xe6rdi. Og vogt dig for heltene - stedet m\xe5 v\xe6re st\xe6rkt bevogtet.\n \nDu har dine ordrer. Portalen er klar. Af sted. Og svigt mig ikke.|" },
	{ 474, "Den n\xe6ste mission er... jeg finder den morsom. En trop af elitekrigere, som heltene sendte for at hj\xe6lpe dem, der k\xe6mper mod d\xe6moner i katedralen. Men de for vild i Den Hjems\xf8gte Labyrint. Det er en belejlig chance for os til at hj\xe6lpe disse kretinere med at finde vej. Tag derhen med det samme og hj\xe6lp dem. Jeg forst\xe5r, du ved, hvilken slags hj\xe6lp jeg taler om...|" },
	{ 475, "Sejren er n\xe6r. Min h\xe6r presser heltene tilbage mod overfladen, vi er der n\xe6sten. Og vi er n\xe6sten f\xe6rdige.\n \nEn af heltenes elitetropper har fanget en af mine tro tjenere: Slagteren. Jeg vil have dig til at rejse til kirkens sakristik\xe6lder, hvor de holder ham, og befri ham. Han vil f\xf8lge dig i det sidste slag, der kommer.|" },
	{ 476, "Ahh, friskt k\xf8""d!\n \nDet er en sp\xf8g, bare rolig. Jeg taler ikke h\xe5rdt til mine egne. Det er s\xe5""dan, jeg plejer at hilse p\xe5 helte. De ser altid skr\xe6mte ud og l\xf8""ber deres vej med et v\xe5""dt spor efter sig. For pokker, det er p\xe5 tide, de begynder at kalde mig pisvandreren af den grund.\n \nN\xe5, det tog dig l\xe6nge nok at n\xe5 herhen.\n \nHer er, hvad vi g\xf8r. Mesterens ordrer lyder, at jeg slutter mig til dig og hj\xe6lper med at hakke og sk\xe6re nogle helte. Det er, hvad vi g\xf8r.\n \nDerefter sender mesteren dig til overfladen. Hvor vi ender denne menneskelige modstand \xe9n gang for alle.\n \nN\xe5, f\xf8r an.|" },
	{ 477, "S\xe5 er det nu. Vores sidste slag med denne by. Mens du var borte p\xe5 dine missioner, har min h\xe6r \xf8""delagt og br\xe6ndt landsbyen ovenover og dr\xe6""bt alle. Vi har sejret. Menneskets trussel er udryddet. Deres elitekrigere flygtede til nabolandsbyen Ravenholm. Mine spejdere melder, at landsbyens smed er steget af sin grav og f\xf8rer en horde zombier mod stedet. Mere ynkeligt kan det ikke blive.\n \nSkaf disse kretinere af vejen og meld tilbage. V\xe6r hurtig. Jeg har st\xf8rre bekymringer, jeg m\xe5 se til.|" },
	{ 478, "Godt arbejde.\n \nDet er en storsl\xe5""et finale for denne by.\n \nJeg lader nogle af mine h\xe5ndlangere indrette og bef\xe6ste stedet; de vil bruge det som base til at \xf8se flere d\xe6moner ind i denne verden.\n \nOg du - din rolle er endnu ikke udspillet.\n \nFor nogen tid siden fors\xf8gte jeg at bes\xe6tte sindet hos kong Leoric, der herskede over dette land. Men efter alle \xe5rene i fangenskab under denne forbandede katedral var jeg ikke st\xe6rk nok. Kongen mistede forstanden. Og gode Lazarus foreslog, at jeg fors\xf8gte det samme med hans yngre s\xf8n Albrecht. Den plan lykkedes. Og jeg har brugt Albrechts krop som kar siden da. Men jeg beh\xf8ver et nyt. En st\xe6rkere krop.\n \nJeg har fulgt din fremgang med interesse og besluttet, at du skal hj\xe6lpe mig med dette. Jeg sp\xf8rger ikke, det er besluttet. Ritualet begynder om lidt i Pandemonium, de m\xf8rke pr\xe6ster har forberedt alt.\n \nN\xe5r det er overst\xe5""et, agter jeg at rejse mod \xf8st, hinsides Aranochs \xf8rkener, for at finde min \xe6ldre bror, der er f\xe6ngslet i en grav d\xe9r.\n \nTr\xe6""d ind i portalen, vi er ventet.|" },
};
