// -----------------------------------------------------------------------------
static bool isPlaceholder( const UiStr& r )  { return r.en == 0 && r.da == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index == 0 && r.da == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* DA_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(DA_Ui);           return DA_Ui;
		case OVL_MENU:          *n = countRows(DA_Menu);         return DA_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(DA_UniqueItem);   return DA_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(DA_AffixPrefix);  return DA_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(DA_AffixSuffix);  return DA_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(DA_BaseItem);     return DA_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(DA_BaseName2);    return DA_BaseName2;
		case OVL_ELEMENT:       *n = countRows(DA_Element);      return DA_Element;
		case OVL_SPICIES:       *n = countRows(DA_Spicies);      return DA_Spicies;
		case OVL_ICEAGE:        *n = countRows(DA_IceAge);       return DA_IceAge;
		case OVL_SPELL:         *n = countRows(DA_Spell);        return DA_Spell;
		case OVL_SPELL_NOM:     *n = countRows(DA_SpellNom);     return DA_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(DA_PerkName);     return DA_PerkName;
		case OVL_PERK_DESC:     *n = countRows(DA_PerkDesc);     return DA_PerkDesc;
		case OVL_WARP:          *n = countRows(DA_Warp);         return DA_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* DA_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:    *n = countRows(DA_Speech);     return DA_Speech;
		case OVL_ONSCREEN:  *n = countRows(DA_OnScreen);   return DA_OnScreen;
		case OVL_QUEST:     *n = countRows(DA_Quest);      return DA_Quest;
	}
	*n = 0; return 0;
}

