// (th4) Game Changer descriptions. The \n markers are the info window's own layout
// (title, category line, body) and are preserved one-for-one from the English text.
const char* DA_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Ingen (sprunget over)";
		case 1: return "Autogem\n\n\n\xc6ndrer spillestilen\n\nFjerner behovet for at gemme spillet manuelt; der gemmes automatisk, ligesom i flerspillertilstand.";
		case 2: return "Bundet udstyr\n\n\n\xd8ger udfordringen\n\nG\xf8r det umuligt at tage genstande p\xe5 eller af under kamp (undtagen h\xe5ndpladser).";
		case 3: return "Genstandsdrop\n\n\n\xd8ger udfordringen\n\nN\xe5r du d\xf8r, taber du dine b\xe5rne genstande.\n\nAdvarsel: hentes de tabte genstande ikke i samme spilsession, forsvinder de.";
		case 4: return "Ubesv\xe6ret\n\n\nG\xf8r spillet lettere\n\nMonstre g\xf8r kun halv skade p\xe5 dig.\nLettere bliver det ikke.";
		case 5: return "Lev af landet\n\n\n\xd8ger udfordringen\n\nByboerne s\xe6lger dig ingen genstande.\n\nDe holder dog ikke op med at yde deres service: sladder, questdialoger, reparation, identifikation, fortryllelse, h\xe5ndv\xe6rk, fatninger og genopladning.";
		case 6: return "Umuligt\n\n\nG\xf8r spillet sv\xe6rere\n\nMonstre g\xf8r dobbelt skade p\xe5 dig.\nSv\xe6rere bliver det ikke.";
		case 7: return "Forbud\n\n\n\xd8ger udfordringen\n\nMonstre taber ikke l\xe6ngere stat-eliksirer tilf\xe6ldigt\nBem\xe6rk: fordelen Storddrikker giver stadig eliksirer fra unikke monstre";
		case 8: return "Fuld kontakt\n\n\nG\xf8r spillet lettere\n\nMonstre med afstandsangreb tr\xe6kker sig ikke tilbage.";
		case 9: return "Nattens sl\xe6gt\n\n\nG\xf8r dig til vampyr\n\nDu lever og d\xf8r ved blodet. Din sult er um\xe6ttelig, men du har alle midler til at jage de svage\n\nDette \xe6ndrer spillet.\nDu bruger ikke genstande, men stoler p\xe5 dine medf\xf8""dte kr\xe6""fter.";
		case 10: return "Hak og snit\n\n\nG\xf8r spillet lettere\n\nDu beh\xf8ver ikke l\xe6ngere skifte v\xe5""bentype (skarp eller stump) efter monstertype. Alle v\xe5""ben g\xf8r standardskade mod alle monsterarter.";
		case 11: return "Vaccineret\n\n\nG\xf8r spillet lettere\n\nMonstre mister alle immuniteter, og du beh\xf8ver ikke skifte formularer - enhver formulartype virker.\nStenforbandelse, Knogle\xe5nd, Elemental og hellige formularer er up\xe5virkede.";
		case 12: return "Det er min hemmelighed\n\n\nG\xf8r spillet lettere\n\nRaseri har ingen nedk\xf8ling og kan kastes igen, s\xe5 snart det slutter.";
		case 13: return "Ingen regenerering\n\n\n\xd8ger udfordringen\n\nKarakteren har ingen basal regenerering af liv og mana.";
		case 14: return "Rene h\xe6nder\n\n\n\xd8ger udfordringen\n\nMonstre taber ikke genstande, karakteren kan b\xe6re.\nSpilleren skal skaffe dem ved k\xf8""b og/eller fortryllelse.";
		case 15: return "Istid\n\n\nKosmetisk \xe6ndring\n\nFangehulsniveauerne ser ud som dybeste vinter, alt er iset og frossent.\nHar du nogensinde forestillet dig, hvordan Helvede ville se ud tilfrosset?";
		case 16: return "Groundhog Day\n\n\n\xc6ndrer spillestilen\n\nSamme fangehul genereres hver gang, befolket af de samme monstre. Du kan spille og forbedre din timing hver gang.";
		case 17: return "H\xe5rdf\xf8re monstre\n\n\nG\xf8r spillet sv\xe6rere\n\nMonstre har +200% livspoint.";
		case 18: return "Uforg\xe6ngelige genstande\n\n\nG\xf8r spillet lettere\n\nGenstande \xf8""del\xe6gges ikke, hvis holdbarheden n\xe5r nul. I stedet bliver de ubrugelige, indtil de repareres.";
		case 19: return "Intet kort\n\n\n\xd8ger udfordringen\n\nAutokortet er utilg\xe6ngeligt\nDu m\xe5 finde vej i fangehullerne uden at l\xe6ne dig op ad det\n\nF\xf8ler du dig allerede fortabt?";
		case 20: return "Dobbelt skade\n\n\nG\xf8r spillet lettere\n\nDine angreb g\xf8r dobbelt skade p\xe5 monstre\n\nAdvarsel: det kan blive skuffende let.\nV\xe6lg det ikke, hvis du vil bevare kampens sp\xe6nding.";
		case 21: return "Se intet ondt\n\n\n\xd8ger udfordringen\n\nKlarsyn fremh\xe6ver ikke monstre i m\xf8rket.";
		case 22: return "Sort d\xf8""d\n\n\nDu er smittet\n\nDen sorte d\xf8""ds pest har taget dig. Den vil langsomt udvikle symptomer, der til sidst uundg\xe5""eligt vil dr\xe6""be dig.\n\nDu kan ikke kurere den, ikke hele den og ikke standse den. Med tiden bliver den v\xe6rre og v\xe6rre. Der er ingen flugt fra denne d\xf8""delige sygdom.";
		case 23: return "Uheld\n\n\n\xd8ger udfordringen\n\nHeldet slipper op f\xf8r eller siden. Dit begyndte aldrig.\n\nStart spillet med alle stats lig 5. F\xe5 kun 2 statpoint ved niveaustigning. Magifund, opn\xe5""et erfaring og guldfund mindsket med 75%. Start spillet uden genstande.\n\nIngen fordele til at hj\xe6lpe dig med erfaring, eliksirdrop, magifund og statpoint ved niveaustigning.";
		case 24: return "Sk\xe5nsell\xf8st jern\n\n\n\xd8ger udfordringen\n\nKlassisk Diablo Ironman var anderledes.\n\nDer var ingen bonus til stats pr. niveaustigning, ingen ekstra erfaring, ingen olier og ID'er fra bosser. Heller ingen forbedring af magifund.\n\nDenne GC f\xf8rer dig tilbage til de r\xf8""dder.";
		case 25: return "Acceleration\n\n\nG\xf8r spillet lettere\n\nErfaring \xf8ges 2x.";
		case 26: return "Askese\n\n\n\xd8ger udfordringen\n\nSpillet gemmes automatisk.\n\nGenstande tabes ved d\xf8""d. Du kan ikke genoplives i byen (du m\xe5 starte et nyt spil), og alle tabte genstande g\xe5r derfor tabt.\n\nDet er som Hardcore, men i stedet for at miste din karakter mister du dine b\xe5rne genstande.";
		case 27: return "Terminator\n\n\nDu er en enhed fra Cyberdyne Systems' serie. Model 101, infiltrator. CPU i l\xe6se-skrive-tilstand aktiveret. Sendt tilbage i tiden for at udf\xf8re mission.\n\nPrim\xe6rt m\xe5l: Uber Diablo.\n\nSekund\xe6rt m\xe5l: udryd monstre.\n\nBetingelse: fremst\xe5 som menneske for lokale subjekter.\n\nBasisopgraderinger installeret. Yderligere opgraderinger tilg\xe6ngelige via selvl\xe6ring.";
		case 28: return "Supermutant\n\n\nDin krop kan sl\xe6""be v\xe5""ben, der ville kn\xe6kke en almindelig mand midt over.\n\nMiniguns.\n\nTing, der ikke burde findes i denne verden. Du kaster ikke l\xe6ngere formularer. Du beh\xf8ver det ikke.\n\nN\xe5r du trykker p\xe5 aftr\xe6kkeren, river salven sig gennem helvedesyngel som papir i en storm.";
		case 29: return "Enklavesoldat\n\n\nSoldat fra Enklavens v\xe6""bnede styrker, tr\xe6net til at udrydde mutanter og genetisk urenhed.\n\nHan er strandet i en verden, der aldrig har kendt atomild, men som har snavs af en anden slags - helvedesyngel.\n\nFjenden har \xe6ndret sig. Form\xe5let har ikke.\n\nEvner: f\xf8rer energiv\xe5""ben og uds\xe6tter kampdroner. Dygtig i elementkrigsf\xf8relse.";
	}
	return nullptr;
}
