// Titles are translated (Abbot -> Abbed, Bishop -> Biskop, Captain -> Kaptajn); coined
// compound names become Danish compounds the way FR renders them (Blazekill ->
// Flammedrab); "X the Y" epithets keep X and translate Y (Ludwig den Paranoide).
